// frontend/src/services/twilioService.js
import axios from 'axios';

const API = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:5000/api',
  headers: {
    'Content-Type': 'application/json',
  },
});

// Send WhatsApp message via backend API (CORRECTED)
export const sendWhatsAppMessage = async (phone, message) => {
  try {
    // Remove 'whatsapp:' prefix from phone number
    const cleanPhone = phone.replace('whatsapp:', '');
    
    const response = await API.post('/whatsapp/send', {
      phone: cleanPhone,
      message: message
    });
    return response.data;
  } catch (error) {
    console.error('Error sending WhatsApp message:', error);
    throw error.response?.data || error;
  }
};

// Send WhatsApp with media via backend API (CORRECTED)
export const sendWhatsAppWithMedia = async (phone, message, mediaBase64, filename, contentType) => {
  try {
    // Remove 'whatsapp:' prefix from phone number
    const cleanPhone = phone.replace('whatsapp:', '');
    
    // For simplicity, just send as text message for now
    const response = await API.post('/whatsapp/send', {
      phone: cleanPhone,
      message: `${message}\n\n📎 File: ${filename}`
    });
    return response.data;
  } catch (error) {
    console.error('Error sending WhatsApp with media:', error);
    throw error.response?.data || error;
  }
};

// Test WhatsApp connection
export const testWhatsApp = async (testPhone) => {
  try {
    const response = await API.post('/whatsapp/test-send', {
      testPhone
    });
    return response.data;
  } catch (error) {
    console.error('Error testing WhatsApp:', error);
    throw error.response?.data || error;
  }
};

// Keep init function for compatibility
export const initTwilio = () => {
  console.log('Twilio will be used via backend API');
  return true;
};