import {
  Percent,
  PlusCircle,
  Search,
  Edit,
  Trash2,
  X,
  Tag,
  CheckCircle,
  XCircle,
  TrendingDown,
  Info,
  Loader2
} from 'lucide-react';
import { useState, useEffect, useCallback } from 'react';
import { discountAPI } from '../services/api';
import toast, { Toaster } from 'react-hot-toast';

const DiscountManagement = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState('all');
  const [showFormModal, setShowFormModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [selectedDiscount, setSelectedDiscount] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  
  // Color constants
  const brandGreen = '#A8E4A0';
  const deepGreen = '#059669';
  const softGreen = '#F0FDF4';

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    type: 'percentage',
    value: '',
    minBillAmount: '0',
    description: '',
    status: 'active'
  });

  const [discounts, setDiscounts] = useState([]);
  const [initialLoad, setInitialLoad] = useState(true);

  // FETCH DISCOUNTS
  const fetchDiscounts = useCallback(async (showToast = false) => {
    if (showToast || initialLoad) {
      setIsLoading(true);
    }
    
    try {
      const data = await discountAPI.getAllDiscounts();
      setDiscounts(data);
      if (showToast && data.length > 0) {
        toast.success(`Loaded ${data.length} discounts`);
      }
    } catch (error) {
      console.error('Failed to fetch discounts:', error);
      if (showToast) {
        toast.error('Failed to load discounts');
      }
    } finally {
      setIsLoading(false);
      setInitialLoad(false);
    }
  }, [initialLoad]);

  // Load discounts on first render
  useEffect(() => {
    fetchDiscounts(false);
  }, [fetchDiscounts]);

  // SEARCH FUNCTIONALITY
  useEffect(() => {
    const handleSearch = async () => {
      if (!searchTerm.trim()) {
        fetchDiscounts(false);
        return;
      }
      
      try {
        const data = await discountAPI.searchDiscounts(searchTerm);
        setDiscounts(data);
      } catch (error) {
        console.error('Search failed:', error);
      }
    };

    const timer = setTimeout(handleSearch, 500);
    return () => clearTimeout(timer);
  }, [searchTerm, fetchDiscounts]);

  const handleOpenAddModal = () => {
    setIsEditing(false);
    setFormData({ 
      name: '', 
      type: 'percentage', 
      value: '', 
      minBillAmount: '0', 
      description: '', 
      status: 'active' 
    });
    setShowFormModal(true);
  };

  const handleOpenEditModal = (discount) => {
    setIsEditing(true);
    setSelectedDiscount(discount);
    setFormData({
      name: discount.name,
      type: discount.type,
      value: discount.value.toString(),
      minBillAmount: discount.minBillAmount.toString(),
      description: discount.description || '',
      status: discount.status
    });
    setShowFormModal(true);
  };

  const handleSaveDiscount = async (e) => {
    e.preventDefault();
    setIsSaving(true);

    try {
      const discountData = {
        name: formData.name.trim(),
        type: formData.type,
        value: parseFloat(formData.value),
        minBillAmount: parseFloat(formData.minBillAmount) || 0,
        description: formData.description.trim(),
        status: formData.status
      };

      if (isEditing && selectedDiscount) {
        // Update existing discount
        const updatedDiscount = await discountAPI.updateDiscount(selectedDiscount._id, discountData);
        setDiscounts(prevDiscounts => 
          prevDiscounts.map(d => d._id === updatedDiscount._id ? updatedDiscount : d)
        );
        toast.success('Discount updated successfully!');
      } else {
        // Create new discount
        const newDiscount = await discountAPI.createDiscount(discountData);
        setDiscounts(prevDiscounts => [newDiscount, ...prevDiscounts]);
        toast.success('Discount added successfully!');
      }
      
      setShowFormModal(false);
    } catch (error) {
      const errorMsg = error.message || 'Error saving discount';
      toast.error(errorMsg);
      console.error('Save error:', error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this discount rule?")) {
      return;
    }

    try {
      await discountAPI.deleteDiscount(id);
      setDiscounts(prevDiscounts => prevDiscounts.filter(d => d._id !== id));
      toast.success('Discount deleted successfully!');
    } catch (error) {
      toast.error('Error deleting discount');
      console.error('Delete error:', error);
    }
  };

  const getStatusBadge = (status) => {
    return status === 'active' 
      ? { bg: '#D1FAE5', color: '#065F46', icon: CheckCircle, label: 'Active' }
      : { bg: '#FEE2E2', color: '#991B1B', icon: XCircle, label: 'Disabled' };
  };

  const filteredDiscounts = discounts.filter(d => {
    if (!d) return false;
    
    const matchesSearch = d.name?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesType = filterType === 'all' || d.type === filterType;
    
    return matchesSearch && matchesType;
  });

  if (isLoading && initialLoad) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen">
        <Loader2 className="animate-spin mb-4" size={48} color={deepGreen} />
        <p className="text-gray-600">Loading discounts...</p>
      </div>
    );
  }

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
      <Toaster position="top-right" />
      
      {/* Header */}
      <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 flex items-center gap-2">
            <TrendingDown style={{ color: deepGreen }} /> Billing Discounts
          </h1>
          <p className="text-gray-600 font-medium">Configure automatic and manual discounts for the POS system</p>
        </div>
        <button
          onClick={handleOpenAddModal}
          className="px-6 py-3 text-white rounded-xl flex items-center gap-2 hover:brightness-90 transition shadow-lg font-bold"
          style={{ backgroundColor: deepGreen }}
        >
          <PlusCircle size={20} /> Add Discount Rule
        </button>
      </div>

      {/* Toolbar */}
      <div className="bg-white p-4 rounded-2xl shadow-sm mb-6 flex flex-col md:flex-row gap-4 border border-gray-100">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            className="w-full pl-10 pr-4 py-2.5 border rounded-xl focus:ring-2 focus:ring-emerald-100 outline-none transition-all"
            placeholder="Search discount by name..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <select
          className="px-4 py-2 border rounded-xl outline-none bg-white font-medium text-gray-700"
          value={filterType}
          onChange={(e) => setFilterType(e.target.value)}
        >
          <option value="all">All Discount Types</option>
          <option value="percentage">Percentage (%)</option>
          <option value="fixed_amount">Fixed Amount (₹)</option>
        </select>
      </div>

      {/* Table */}
      <div className="bg-white rounded-2xl shadow-sm overflow-hidden border border-gray-100 overflow-x-auto">
        {discounts.length === 0 ? (
          <div className="p-8 text-center">
            <Percent size={48} className="mx-auto text-gray-300 mb-4" />
            <h3 className="text-lg font-medium text-gray-700 mb-2">No discounts found</h3>
            <p className="text-gray-500">Create your first discount rule to get started</p>
          </div>
        ) : (
          <table className="w-full text-left min-w-[800px]">
            <thead style={{ backgroundColor: `${softGreen}` }} className="border-b">
              <tr>
                <th className="px-6 py-4 font-bold" style={{ color: deepGreen }}>Discount Name</th>
                <th className="px-6 py-4 font-bold" style={{ color: deepGreen }}>Value</th>
                <th className="px-6 py-4 font-bold" style={{ color: deepGreen }}>Requirement</th>
                <th className="px-6 py-4 font-bold" style={{ color: deepGreen }}>Usage History</th>
                <th className="px-6 py-4 font-bold" style={{ color: deepGreen }}>Status</th>
                <th className="px-6 py-4 font-bold text-right" style={{ color: deepGreen }}>Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredDiscounts.map(discount => {
                const status = getStatusBadge(discount.status);
                const StatusIcon = status.icon;
                return (
                  <tr key={discount._id} className="hover:bg-emerald-50/20 transition">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="p-2.5 rounded-xl shadow-sm" style={{ backgroundColor: brandGreen }}>
                          <Tag size={20} style={{ color: deepGreen }} />
                        </div>
                        <div>
                          <p className="font-bold text-gray-900">{discount.name}</p>
                          <p className="text-xs text-gray-500 max-w-[200px] truncate">{discount.description}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="px-3 py-1 bg-emerald-50 rounded-lg font-black text-sm" style={{ color: deepGreen }}>
                        {discount.type === 'percentage' ? `${discount.value}% OFF` : `₹${discount.value} OFF`}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <p className="text-sm font-semibold text-gray-700">Min Bill: ₹{discount.minBillAmount?.toLocaleString() || '0'}</p>
                    </td>
                    <td className="px-6 py-4 text-sm font-bold text-gray-600">
                      {discount.totalApplied || 0} Bills
                    </td>
                    <td className="px-6 py-4">
                      <span className="flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-black uppercase tracking-tight"
                        style={{ backgroundColor: status.bg, color: status.color }}>
                        <StatusIcon size={14} /> {status.label}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => handleOpenEditModal(discount)} 
                          className="p-2 hover:bg-emerald-100 rounded-lg transition-colors" 
                          style={{ color: deepGreen }}
                        >
                          <Edit size={18} />
                        </button>
                        <button 
                          onClick={() => handleDelete(discount._id)} 
                          className="p-2 hover:bg-red-100 text-red-600 rounded-lg transition-colors"
                        >
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      {/* Form Modal */}
      {showFormModal && (
        <Modal onClose={() => !isSaving && setShowFormModal(false)}>
          <div className="flex items-center gap-2 mb-6" style={{ color: deepGreen }}>
            <Percent size={24} className="p-1 rounded" style={{ backgroundColor: brandGreen }} />
            <h2 className="text-2xl font-black">{isEditing ? 'Edit Discount Rule' : 'New Discount Rule'}</h2>
          </div>
          
          <form onSubmit={handleSaveDiscount} className="space-y-5">
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1">Display Name</label>
              <input 
                required 
                placeholder="e.g. Employee Discount"
                className="w-full border-2 border-gray-100 p-3 rounded-xl focus:border-emerald-400 outline-none transition-all font-semibold"
                value={formData.name}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
                disabled={isSaving}
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Calculation Type</label>
                <select 
                  className="w-full border-2 border-gray-100 p-3 rounded-xl outline-none font-semibold"
                  value={formData.type}
                  onChange={(e) => setFormData({...formData, type: e.target.value})}
                  disabled={isSaving}
                >
                  <option value="percentage">Percentage (%)</option>
                  <option value="fixed_amount">Fixed Amount (₹)</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Discount Value</label>
                <input 
                  type="number" 
                  required 
                  className="w-full border-2 border-gray-100 p-3 rounded-xl outline-none font-semibold"
                  value={formData.value}
                  onChange={(e) => setFormData({...formData, value: e.target.value})}
                  min="0"
                  step={formData.type === 'percentage' ? '0.01' : '1'}
                  disabled={isSaving}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1">Minimum Bill Amount (₹)</label>
              <input 
                type="number" 
                className="w-full border-2 border-gray-100 p-3 rounded-xl outline-none font-semibold"
                value={formData.minBillAmount}
                onChange={(e) => setFormData({...formData, minBillAmount: e.target.value})}
                min="0"
                disabled={isSaving}
              />
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1 flex items-center gap-1">
                Description <Info size={14} className="text-gray-400" />
              </label>
              <textarea 
                rows="2" 
                className="w-full border-2 border-gray-100 p-3 rounded-xl outline-none font-semibold"
                placeholder="Internal notes for cashiers..."
                value={formData.description}
                onChange={(e) => setFormData({...formData, description: e.target.value})}
                disabled={isSaving}
              />
            </div>

            <div className="flex gap-4 pt-2">
              <button 
                type="button" 
                onClick={() => setShowFormModal(false)} 
                className="flex-1 py-3.5 bg-gray-100 text-gray-600 rounded-xl font-bold hover:bg-gray-200 transition-all disabled:opacity-50"
                disabled={isSaving}
              >
                Cancel
              </button>
              <button 
                type="submit" 
                className="flex-[2] py-3.5 text-white rounded-xl font-bold shadow-lg transition-all active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2"
                style={{ backgroundColor: deepGreen }}
                disabled={isSaving}
              >
                {isSaving ? (
                  <>
                    <Loader2 className="animate-spin" size={20} />
                    {isEditing ? 'Saving...' : 'Creating...'}
                  </>
                ) : isEditing ? (
                  'Save Changes'
                ) : (
                  'Enable Discount'
                )}
              </button>
            </div>
          </form>
        </Modal>
      )}
    </div>
  );
};

/* Reusable Modal Component */
const Modal = ({ children, onClose }) => (
  <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md flex items-center justify-center z-[100] p-4">
    <div className="bg-white rounded-3xl p-8 max-w-lg w-full shadow-2xl animate-in zoom-in-95 duration-200">
      <div className="flex justify-end mb-[-32px]">
        <button onClick={onClose} className="text-gray-400 hover:text-gray-900 p-2 bg-gray-50 rounded-full transition-colors">
          <X size={20} />
        </button>
      </div>
      {children}
    </div>
  </div>
);

export default DiscountManagement;