import {
  Users,
  UserPlus,
  Search,
  Eye,
  Edit,
  Trash2,
  X,
  CheckCircle,
  XCircle,
  Loader2,
  Hash
} from 'lucide-react';
import { useState, useEffect, useCallback } from 'react';
import { customerAPI } from '../services/api';
import toast, { Toaster } from 'react-hot-toast';

const CustomerManagement = () => {
  const darkGreen = '#059669';

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [showFormModal, setShowFormModal] = useState(false);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    address: '',
    status: 'active'
  });

  const [customers, setCustomers] = useState([]);
  const [initialLoad, setInitialLoad] = useState(true);

  // FETCH CUSTOMERS
  const fetchCustomers = useCallback(async (showToast = false) => {
    if (showToast || initialLoad) {
      setIsLoading(true);
    }
    
    try {
      const data = await customerAPI.getAllCustomers();
      setCustomers(data);
      if (showToast && data.length > 0) {
        toast.success(`Loaded ${data.length} customers`);
      }
    } catch (error) {
      console.error('Failed to fetch customers:', error);
      if (showToast) {
        toast.error('Failed to load customers');
      }
    } finally {
      setIsLoading(false);
      setInitialLoad(false);
    }
  }, [initialLoad]);

  // Load customers on first render
  useEffect(() => {
    fetchCustomers(false);
  }, [fetchCustomers]);

  // SEARCH FUNCTIONALITY
  useEffect(() => {
    const handleSearch = async () => {
      if (!searchTerm.trim()) {
        fetchCustomers(false);
        return;
      }
      
      try {
        const data = await customerAPI.searchCustomers(searchTerm);
        setCustomers(data);
      } catch (error) {
        console.error('Search failed:', error);
      }
    };

    const timer = setTimeout(handleSearch, 500);
    return () => clearTimeout(timer);
  }, [searchTerm, fetchCustomers]);

  const handleOpenAddModal = () => {
    setIsEditing(false);
    setFormData({ 
      name: '', 
      phone: '', 
      address: '', 
      status: 'active' 
    });
    setShowFormModal(true);
  };

  const handleOpenEditModal = (customer) => {
    setIsEditing(true);
    setSelectedCustomer(customer);
    setFormData({
      name: customer.name,
      phone: customer.phone,
      address: customer.address || '',
      status: customer.status
    });
    setShowFormModal(true);
  };

  const handleSaveCustomer = async (e) => {
    e.preventDefault();
    setIsSaving(true);

    try {
      const customerData = {
        name: formData.name.trim(),
        phone: formData.phone.trim(),
        address: formData.address.trim(),
        status: formData.status
      };

      if (isEditing && selectedCustomer) {
        // Update existing customer
        const updatedCustomer = await customerAPI.updateCustomer(selectedCustomer._id, customerData);
        setCustomers(prevCustomers => 
          prevCustomers.map(c => c._id === updatedCustomer._id ? updatedCustomer : c)
        );
        toast.success('Customer updated successfully!');
      } else {
        // Create new customer - server will generate customerId
        const newCustomer = await customerAPI.createCustomer(customerData);
        setCustomers(prevCustomers => [newCustomer, ...prevCustomers]);
        toast.success('Customer added successfully!');
      }
      
      setShowFormModal(false);
    } catch (error) {
      const errorMsg = error.message || 'Error saving customer';
      toast.error(errorMsg);
      console.error('Save error:', error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteCustomer = async (id) => {
    if (!window.confirm("Are you sure you want to delete this customer?")) {
      return;
    }

    try {
      await customerAPI.deleteCustomer(id);
      setCustomers(prevCustomers => prevCustomers.filter(c => c._id !== id));
      toast.success('Customer deleted successfully!');
    } catch (error) {
      toast.error('Error deleting customer');
      console.error('Delete error:', error);
    }
  };

  const filteredCustomers = customers.filter(c => {
    if (!c) return false;
    
    const matchSearch =
      c.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.customerId?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.phone?.includes(searchTerm) ||
      c.address?.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchStatus = filterStatus === 'all' || c.status === filterStatus;
    
    return matchSearch && matchStatus;
  });

  const stats = {
    total: customers.length,
    active: customers.filter(c => c.status === 'active').length,
    inactive: customers.filter(c => c.status === 'inactive').length
  };

  const getStatusBadge = (status) => {
    if (status === 'active') {
      return { bg: '#D1FAE5', color: '#065F46', label: 'Active', icon: CheckCircle };
    }
    return { bg: '#FEE2E2', color: '#991B1B', label: 'Inactive', icon: XCircle };
  };

  if (isLoading && initialLoad) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen">
        <Loader2 className="animate-spin mb-4" size={48} color={darkGreen} />
        <p className="text-gray-600">Loading customers...</p>
      </div>
    );
  }

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
      <Toaster position="top-right" />
      
      <div className="mb-6">
        <h1 className="text-3xl font-bold text-gray-800">Customer Management</h1>
        <p className="text-gray-600">Manage customers and their activity</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <StatCard title="Total Customers" value={stats.total} icon={<Users size={24} color={darkGreen} />} />
        <StatCard title="Active Customers" value={stats.active} icon={<CheckCircle size={24} color="#059669" />} />
        <StatCard title="Inactive Customers" value={stats.inactive} icon={<XCircle size={24} color="#dc2626" />} />
      </div>

      <div className="bg-white p-4 rounded-lg shadow-md mb-6 flex flex-col md:flex-row gap-4">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            className="w-full pl-10 pr-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500 focus:border-transparent"
            placeholder="Search by name, ID, phone"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <select
          className="px-4 py-2 border rounded-lg bg-white focus:outline-none focus:ring-2 focus:ring-green-500"
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
        >
          <option value="all">All Status</option>
          <option value="active">Active</option>
          <option value="inactive">Inactive</option>
        </select>

        <button
          onClick={handleOpenAddModal}
          className="px-4 py-2 text-white rounded-lg flex items-center gap-2 hover:brightness-90 transition font-medium"
          style={{ backgroundColor: darkGreen }}
        >
          <UserPlus size={18} /> Add Customer
        </button>
      </div>

      <div className="bg-white rounded-lg shadow-md overflow-x-auto">
        {customers.length === 0 ? (
          <div className="p-8 text-center">
            <Users size={48} className="mx-auto text-gray-300 mb-4" />
            <h3 className="text-lg font-medium text-gray-700 mb-2">No customers found</h3>
            <p className="text-gray-500">Get started by adding your first customer</p>
          </div>
        ) : (
          <table className="w-full">
            <thead style={{ backgroundColor: `${darkGreen}10` }}>
              <tr>
                <th className="px-6 py-4 text-left font-semibold text-gray-700">Customer ID</th>
                <th className="px-6 py-4 text-left font-semibold text-gray-700">Name</th>
                <th className="px-6 py-4 text-left font-semibold text-gray-700">Contact</th>
                <th className="px-6 py-4 text-left font-semibold text-gray-700">Status</th>
                <th className="px-6 py-4 text-left font-semibold text-gray-700">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredCustomers.map(customer => {
                const status = getStatusBadge(customer.status);
                const Icon = status.icon;

                return (
                  <tr key={customer._id} className="border-b hover:bg-gray-50 transition">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <Hash size={14} className="text-gray-400" />
                        <span className="font-mono font-medium text-gray-700">
                          {customer.customerId || 'N/A'}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <p className="font-semibold text-gray-800">{customer.name}</p>
                    </td>
                    <td className="px-6 py-4 text-gray-600">{customer.phone}</td>
                
                    <td className="px-6 py-4">
                      <span
                        className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-semibold"
                        style={{ backgroundColor: status.bg, color: status.color }}
                      >
                        <Icon size={14} />
                        {status.label}
                      </span>
                    </td>
                    <td className="px-6 py-4 flex gap-2">
                      <button
                        onClick={() => { setSelectedCustomer(customer); setShowDetailsModal(true); }}
                        className="p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-colors"
                      >
                        <Eye size={16} />
                      </button>
                      <button 
                        onClick={() => handleOpenEditModal(customer)}
                        className="p-2 bg-emerald-50 rounded-lg hover:bg-emerald-100 transition-colors" 
                        style={{ color: darkGreen }}
                      >
                        <Edit size={16} />
                      </button>
                      <button 
                        onClick={() => handleDeleteCustomer(customer._id)}
                        className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-100 transition-colors"
                      >
                        <Trash2 size={16} />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      {showFormModal && (
        <Modal onClose={() => !isSaving && setShowFormModal(false)}>
          <h2 className="text-xl font-bold mb-4 text-gray-800">
            {isEditing ? 'Edit Customer' : 'Add New Customer'}
          </h2>
          <form onSubmit={handleSaveCustomer} className="space-y-4">
            <div>
              <label className="block text-sm font-medium mb-1 text-gray-700">
                Full Name <span className="text-red-500">*</span>
              </label>
              <input 
                required
                className="w-full border p-2 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                value={formData.name}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
                placeholder="Enter full name"
                disabled={isSaving}
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1 text-gray-700">
                Phone Number <span className="text-red-500">*</span>
              </label>
              <input 
                type="tel"
                required
                className="w-full border p-2 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                value={formData.phone}
                onChange={(e) => setFormData({...formData, phone: e.target.value})}
                placeholder="9876543210"
                disabled={isSaving}
                pattern="[0-9]{10}"
                title="Please enter a valid 10-digit phone number"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1 text-gray-700">
                Address
              </label>
              <textarea 
                rows="2"
                className="w-full border p-2 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                value={formData.address}
                onChange={(e) => setFormData({...formData, address: e.target.value})}
                placeholder="Customer address"
                disabled={isSaving}
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1 text-gray-700">
                Status
              </label>
              <select 
                className="w-full border p-2 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                value={formData.status}
                onChange={(e) => setFormData({...formData, status: e.target.value})}
                disabled={isSaving}
              >
                <option value="active">Active</option>
                <option value="inactive">Inactive</option>
              </select>
            </div>
            <div className="bg-gray-50 p-3 rounded-lg">
              <p className="text-sm text-gray-600 mb-1">
                {isEditing ? (
                  <span className="flex items-center gap-2">
                    <Hash size={14} className="text-gray-500" />
                    Customer ID: <span className="font-mono font-medium">{selectedCustomer?.customerId}</span>
                  </span>
                ) : (
                  "A unique Customer ID will be automatically generated upon saving."
                )}
              </p>
            </div>
            <button 
              type="submit"
              disabled={isSaving}
              className="w-full py-2 text-white rounded-lg font-semibold hover:brightness-90 transition flex items-center justify-center gap-2 disabled:opacity-50"
              style={{ backgroundColor: darkGreen }}
            >
              {isSaving ? (
                <>
                  <Loader2 className="animate-spin" size={18} />
                  {isEditing ? 'Updating...' : 'Saving...'}
                </>
              ) : isEditing ? (
                'Update Customer'
              ) : (
                'Save Customer'
              )}
            </button>
          </form>
        </Modal>
      )}

      {showDetailsModal && selectedCustomer && (
        <Modal onClose={() => setShowDetailsModal(false)}>
          <div className="space-y-4">
            <h2 className="text-xl font-bold border-b pb-3 text-gray-800">Customer Details</h2>
            <div className="grid grid-cols-2 gap-y-3 text-sm">
              <p className="text-gray-500 font-medium">Customer ID</p>
              <p className="font-mono font-medium text-gray-800 flex items-center gap-1">
                <Hash size={12} className="text-gray-400" />
                {selectedCustomer.customerId || 'N/A'}
              </p>
              
              <p className="text-gray-500 font-medium">Name</p>
              <p className="font-medium text-gray-800">{selectedCustomer.name}</p>
              
              <p className="text-gray-500 font-medium">Phone</p>
              <p className="font-medium text-gray-800">{selectedCustomer.phone}</p>
              
              <p className="text-gray-500 font-medium">Joined Date</p>
              <p className="font-medium text-gray-800">
                {new Date(selectedCustomer.joined).toLocaleDateString()}
              </p>
              
              <p className="text-gray-500 font-medium">Address</p>
              <p className="font-medium text-gray-800">{selectedCustomer.address || 'Not provided'}</p>
              
              <p className="text-gray-500 font-medium">Total Orders</p>
              <p className="font-medium text-gray-800">{selectedCustomer.totalOrders || 0}</p>
              

              
              <p className="text-gray-500 font-medium">Status</p>
              <p>
                <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${selectedCustomer.status === 'active' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                  {selectedCustomer.status === 'active' ? 'Active' : 'Inactive'}
                </span>
              </p>
            </div>
            <button 
              onClick={() => setShowDetailsModal(false)}
              className="w-full mt-4 py-2 bg-gray-100 rounded-lg text-gray-700 hover:bg-gray-200 transition-colors font-medium"
            >
              Close
            </button>
          </div>
        </Modal>
      )}
    </div>
  );
};

/* Reusable components */
const StatCard = ({ title, value, icon }) => (
  <div className="bg-white rounded-lg shadow-md p-6 flex items-center justify-between">
    <div>
      <p className="text-gray-500 text-sm font-medium">{title}</p>
      <p className="text-3xl font-bold text-gray-800">{value}</p>
    </div>
    {icon && <div className="p-3 rounded-xl bg-gray-50">{icon}</div>}
  </div>
);

const Modal = ({ children, onClose }) => (
  <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
    <div className="bg-white rounded-2xl p-6 max-w-lg w-full shadow-2xl">
      <div className="flex justify-end mb-2">
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition">
          <X size={20} />
        </button>
      </div>
      {children}
    </div>
  </div>
);

export default CustomerManagement;