import {
  Ticket,
  PlusCircle,
  Search,
  Edit,
  Trash2,
  X,
  Copy,
  Calendar,
  CheckCircle,
  XCircle,
  Clock,
  Users,
  Info,
  Loader2
} from 'lucide-react';
import { useState, useEffect, useCallback } from 'react';
import { couponAPI } from '../services/api';
import toast, { Toaster } from 'react-hot-toast';

const CouponManagement = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [showFormModal, setShowFormModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [selectedCoupon, setSelectedCoupon] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  
  // Color constants
  const brandGreen = '#A8E4A0'; 
  const deepGreen = '#059669';
  const softGreen = '#F0FDF4';

  const [coupons, setCoupons] = useState([]);
  const [initialLoad, setInitialLoad] = useState(true);

  const [formData, setFormData] = useState({
    code: '',
    description: '',
    discountType: 'percentage',
    value: '',
    expiryDate: '',
    usageLimit: '',
    minPurchase: '0'
  });

  // FETCH COUPONS
  const fetchCoupons = useCallback(async (showToast = false) => {
    if (showToast || initialLoad) {
      setIsLoading(true);
    }
    
    try {
      const data = await couponAPI.getAllCoupons();
      setCoupons(data);
      if (showToast && data.length > 0) {
        toast.success(`Loaded ${data.length} coupons`);
      }
    } catch (error) {
      console.error('Failed to fetch coupons:', error);
      if (showToast) {
        toast.error('Failed to load coupons');
      }
    } finally {
      setIsLoading(false);
      setInitialLoad(false);
    }
  }, [initialLoad]);

  // Load coupons on first render
  useEffect(() => {
    fetchCoupons(false);
  }, [fetchCoupons]);

  // SEARCH FUNCTIONALITY
  useEffect(() => {
    const handleSearch = async () => {
      if (!searchTerm.trim()) {
        fetchCoupons(false);
        return;
      }
      
      try {
        const data = await couponAPI.searchCoupons(searchTerm);
        setCoupons(data);
      } catch (error) {
        console.error('Search failed:', error);
      }
    };

    const timer = setTimeout(handleSearch, 500);
    return () => clearTimeout(timer);
  }, [searchTerm, fetchCoupons]);

  const getCouponStatus = (coupon) => {
    const today = new Date().toISOString().split('T')[0];
    const expiryDate = new Date(coupon.expiryDate).toISOString().split('T')[0];
    
    if (coupon.usageCount >= coupon.usageLimit) return 'redeemed';
    if (expiryDate < today) return 'expired';
    return 'live';
  };

  const getStatusStyle = (status) => {
    switch (status) {
      case 'live': return { bg: '#D1FAE5', color: '#065F46', icon: CheckCircle, label: 'Live' };
      case 'expired': return { bg: '#FEE2E2', color: '#991B1B', icon: XCircle, label: 'Expired' };
      case 'redeemed': return { bg: '#FEF3C7', color: '#92400E', icon: Clock, label: 'Fully Used' };
      default: return { bg: '#F3F4F6', color: '#374151', icon: Info, label: 'Unknown' };
    }
  };

  const handleOpenAddModal = () => {
    setIsEditing(false);
    setFormData({ 
      code: '', 
      description: '', 
      discountType: 'percentage', 
      value: '', 
      expiryDate: '', 
      usageLimit: '', 
      minPurchase: '0' 
    });
    setShowFormModal(true);
  };

  const handleOpenEditModal = (coupon) => {
    setIsEditing(true);
    setSelectedCoupon(coupon);
    setFormData({
      code: coupon.code,
      description: coupon.description || '',
      discountType: coupon.discountType,
      value: coupon.value.toString(),
      expiryDate: new Date(coupon.expiryDate).toISOString().split('T')[0],
      usageLimit: coupon.usageLimit.toString(),
      minPurchase: coupon.minPurchase?.toString() || '0'
    });
    setShowFormModal(true);
  };

  const handleSave = async (e) => {
    e.preventDefault();
    setIsSaving(true);

    try {
      const couponData = {
        code: formData.code.trim(),
        description: formData.description.trim(),
        discountType: formData.discountType,
        value: parseFloat(formData.value),
        expiryDate: formData.expiryDate,
        usageLimit: parseInt(formData.usageLimit),
        minPurchase: parseFloat(formData.minPurchase) || 0
      };

      if (isEditing && selectedCoupon) {
        // Update existing coupon
        const updatedCoupon = await couponAPI.updateCoupon(selectedCoupon._id, couponData);
        setCoupons(prevCoupons => 
          prevCoupons.map(c => c._id === updatedCoupon._id ? updatedCoupon : c)
        );
        toast.success('Coupon updated successfully!');
      } else {
        // Create new coupon
        const newCoupon = await couponAPI.createCoupon(couponData);
        setCoupons(prevCoupons => [newCoupon, ...prevCoupons]);
        toast.success('Coupon created successfully!');
      }
      
      setShowFormModal(false);
    } catch (error) {
      const errorMsg = error.message || 'Error saving coupon';
      toast.error(errorMsg);
      console.error('Save error:', error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Permanently delete this coupon?")) {
      return;
    }

    try {
      await couponAPI.deleteCoupon(id);
      setCoupons(prevCoupons => prevCoupons.filter(c => c._id !== id));
      toast.success('Coupon deleted successfully!');
    } catch (error) {
      toast.error('Error deleting coupon');
      console.error('Delete error:', error);
    }
  };

  // Copy coupon code to clipboard
  const copyToClipboard = async (code) => {
    try {
      await navigator.clipboard.writeText(code);
      toast.success(`Copied: ${code}`);
    } catch (error) {
      toast.error('Failed to copy');
    }
  };

  const filteredCoupons = coupons.filter(c => {
    if (!c) return false;
    
    const status = getCouponStatus(c);
    const matchesSearch = c.code?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         c.description?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filterStatus === 'all' || status === filterStatus;
    
    return matchesSearch && matchesFilter;
  });

  if (isLoading && initialLoad) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen">
        <Loader2 className="animate-spin mb-4" size={48} color={deepGreen} />
        <p className="text-gray-600">Loading coupons...</p>
      </div>
    );
  }

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
      <Toaster position="top-right" />
      
      {/* Header */}
      <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-800 flex items-center gap-2">
            <Ticket style={{ color: deepGreen }} /> Coupon Codes
          </h1>
          <p className="text-gray-600 font-medium">Create and track marketing coupon campaigns</p>
        </div>
        <button
          onClick={handleOpenAddModal}
          className="px-6 py-3 text-white rounded-xl flex items-center gap-2 hover:brightness-90 transition shadow-lg font-bold"
          style={{ backgroundColor: deepGreen }}
        >
          <PlusCircle size={20} /> Create Coupon
        </button>
      </div>

      {/* Toolbar */}
      <div className="bg-white p-4 rounded-2xl shadow-sm mb-6 flex flex-col md:flex-row gap-4 border border-gray-100">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            className="w-full pl-10 pr-4 py-2.5 border rounded-xl focus:ring-2 focus:ring-emerald-100 outline-none transition-all"
            placeholder="Search by code (e.g. WINTER50)..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <select
          className="px-4 py-2 border rounded-xl outline-none bg-white font-bold text-gray-700"
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
        >
          <option value="all">All Status</option>
          <option value="live">Live Now</option>
          <option value="expired">Expired</option>
          <option value="redeemed">Redeemed</option>
        </select>
      </div>

      {/* Table */}
      <div className="bg-white rounded-2xl shadow-sm overflow-hidden border border-gray-100 overflow-x-auto">
        {coupons.length === 0 ? (
          <div className="p-8 text-center">
            <Ticket size={48} className="mx-auto text-gray-300 mb-4" />
            <h3 className="text-lg font-medium text-gray-700 mb-2">No coupons found</h3>
            <p className="text-gray-500">Create your first coupon campaign to get started</p>
          </div>
        ) : (
          <table className="w-full text-left min-w-[900px]">
            <thead style={{ backgroundColor: softGreen }} className="border-b">
              <tr>
                <th className="px-6 py-4 font-bold" style={{ color: deepGreen }}>Coupon Code</th>
                <th className="px-6 py-4 font-bold" style={{ color: deepGreen }}>Value</th>
                <th className="px-6 py-4 font-bold" style={{ color: deepGreen }}>Usage Progress</th>
                <th className="px-6 py-4 font-bold" style={{ color: deepGreen }}>Expiry</th>
                <th className="px-6 py-4 font-bold" style={{ color: deepGreen }}>Status</th>
                <th className="px-6 py-4 font-bold text-right" style={{ color: deepGreen }}>Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredCoupons.map(coupon => {
                const status = getCouponStatus(coupon);
                const style = getStatusStyle(status);
                const StatusIcon = style.icon;
                const progress = (coupon.usageCount / coupon.usageLimit) * 100;

                return (
                  <tr key={coupon._id} className="hover:bg-emerald-50/20 transition">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="p-2.5 rounded-xl border-2 border-dashed" style={{ borderColor: brandGreen, backgroundColor: softGreen }}>
                          <p className="font-black text-sm uppercase tracking-widest" style={{ color: deepGreen }}>
                            {coupon.code}
                          </p>
                        </div>
                        <div>
                          <p className="text-xs text-gray-500 max-w-[150px] truncate">{coupon.description || 'No description'}</p>
                          <button
                            onClick={() => copyToClipboard(coupon.code)}
                            className="text-xs text-gray-400 hover:text-gray-600 flex items-center gap-1 mt-1"
                          >
                            <Copy size={10} /> Copy
                          </button>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 font-black text-gray-800">
                      {coupon.discountType === 'percentage' ? `${coupon.value}%` : `₹${coupon.value}`}
                      <p className="text-[10px] text-gray-400 font-normal">Min: ₹{coupon.minPurchase?.toLocaleString() || '0'}</p>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-24 h-2 bg-gray-100 rounded-full overflow-hidden">
                          <div 
                            className="h-full transition-all duration-500" 
                            style={{ 
                              width: `${Math.min(progress, 100)}%`, 
                              backgroundColor: progress > 90 ? '#EF4444' : deepGreen 
                            }}
                          ></div>
                        </div>
                        <span className="text-xs font-bold text-gray-600">
                          {coupon.usageCount}/{coupon.usageLimit}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-1.5 text-sm font-semibold text-gray-700">
                        <Calendar size={14} className="text-gray-400" /> 
                        {new Date(coupon.expiryDate).toLocaleDateString()}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider"
                        style={{ backgroundColor: style.bg, color: style.color }}>
                        <StatusIcon size={12} /> {style.label}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => handleOpenEditModal(coupon)} 
                          className="p-2 hover:bg-emerald-100 rounded-lg transition-colors" 
                          style={{ color: deepGreen }}
                        >
                          <Edit size={18} />
                        </button>
                        <button 
                          onClick={() => handleDelete(coupon._id)} 
                          className="p-2 hover:bg-red-100 text-red-600 rounded-lg transition-colors"
                        >
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      {/* Modal */}
      {showFormModal && (
        <Modal onClose={() => !isSaving && setShowFormModal(false)}>
          <div className="flex items-center gap-2 mb-6" style={{ color: deepGreen }}>
            <Ticket size={24} className="p-1 rounded" style={{ backgroundColor: brandGreen }} />
            <h2 className="text-2xl font-black">{isEditing ? 'Edit Coupon' : 'New Coupon'}</h2>
          </div>
          <form onSubmit={handleSave} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Coupon Code</label>
                <input 
                  required 
                  className="w-full border-2 border-gray-100 p-2.5 rounded-xl uppercase font-mono font-bold outline-none focus:border-emerald-400" 
                  value={formData.code} 
                  onChange={e => setFormData({...formData, code: e.target.value.toUpperCase()})}
                  disabled={isSaving}
                />
              </div>
              <div>
                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Discount Type</label>
                <select 
                  className="w-full border-2 border-gray-100 p-2.5 rounded-xl font-bold outline-none" 
                  value={formData.discountType} 
                  onChange={e => setFormData({...formData, discountType: e.target.value})}
                  disabled={isSaving}
                >
                  <option value="percentage">Percentage (%)</option>
                  <option value="fixed">Fixed Amount (₹)</option>
                </select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Value</label>
                <input 
                  type="number" 
                  required 
                  className="w-full border-2 border-gray-100 p-2.5 rounded-xl font-bold outline-none" 
                  value={formData.value} 
                  onChange={e => setFormData({...formData, value: e.target.value})}
                  min="0"
                  step={formData.discountType === 'percentage' ? '0.01' : '1'}
                  disabled={isSaving}
                />
              </div>
              <div>
                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Min. Purchase</label>
                <input 
                  type="number" 
                  className="w-full border-2 border-gray-100 p-2.5 rounded-xl font-bold outline-none" 
                  value={formData.minPurchase} 
                  onChange={e => setFormData({...formData, minPurchase: e.target.value})}
                  min="0"
                  disabled={isSaving}
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Expiry Date</label>
                <input 
                  type="date" 
                  required 
                  className="w-full border-2 border-gray-100 p-2.5 rounded-xl font-bold outline-none" 
                  value={formData.expiryDate} 
                  onChange={e => setFormData({...formData, expiryDate: e.target.value})}
                  disabled={isSaving}
                />
              </div>
              <div>
                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Usage Limit</label>
                <input 
                  type="number" 
                  required 
                  className="w-full border-2 border-gray-100 p-2.5 rounded-xl font-bold outline-none" 
                  value={formData.usageLimit} 
                  onChange={e => setFormData({...formData, usageLimit: e.target.value})}
                  min="1"
                  disabled={isSaving}
                />
              </div>
            </div>
            <div>
              <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Description</label>
              <textarea 
                rows="2"
                className="w-full border-2 border-gray-100 p-2.5 rounded-xl font-bold outline-none" 
                value={formData.description} 
                onChange={e => setFormData({...formData, description: e.target.value})}
                placeholder="Coupon description (optional)"
                disabled={isSaving}
              />
            </div>
            <button 
              type="submit" 
              className="w-full py-4 text-white rounded-xl font-black uppercase tracking-widest shadow-lg transition-all active:scale-95 hover:brightness-90 disabled:opacity-50 flex items-center justify-center gap-2"
              style={{ backgroundColor: deepGreen }}
              disabled={isSaving}
            >
              {isSaving ? (
                <>
                  <Loader2 className="animate-spin" size={20} />
                  {isEditing ? 'Updating...' : 'Creating...'}
                </>
              ) : isEditing ? (
                'Update Coupon'
              ) : (
                'Create Campaign'
              )}
            </button>
          </form>
        </Modal>
      )}
    </div>
  );
};

const Modal = ({ children, onClose }) => (
  <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md flex items-center justify-center z-[100] p-4">
    <div className="bg-white rounded-3xl p-8 max-w-lg w-full shadow-2xl animate-in zoom-in-95 duration-200">
      <div className="flex justify-end mb-[-32px]">
        <button onClick={onClose} className="text-gray-400 hover:text-gray-900 p-2 bg-gray-50 rounded-full transition-colors disabled:opacity-50" disabled={false}>
          <X size={20} />
        </button>
      </div>
      {children}
    </div>
  </div>
);

export default CouponManagement;