import { useState } from 'react';
import BillingManagement from './components/BillingManagement';
import CustomerManagement from './components/CustomerManagement';
import DashboardPage from './components/DashboardPage';
import InvoicePreview from './components/InvoicePreview';
import Sidebar from './components/Layout/Sidebar';
import TopBar from './components/Layout/TopBar';
import LoginPage from './components/LoginPage';
import NotificationsPage from './components/NotificationsPage';
import OrdersManagement from './components/OrdersManagement';
import PaymentPage from './components/PaymentPage';
import ProductManagement from './components/pm';
import Reports from './components/Reports';
import SalesHistory from './components/SalesHistory';
import StockManagement from './components/StockManagement';
import DiscountManagement from './components/discount';
import CouponManagement from './components/coupons';
import TaxManagement from './components/gst';
import Expense from './components/Expense';
import CoinBillingSystem from './components/coinwallet';

function App() { 
  const [isLoggedIn, setIsLoggedIn] = useState(false); 
  const [currentUser, setCurrentUser] = useState(null); 
  const [currentPage, setCurrentPage] = useState('dashboard'); 
  const [isMobileOpen, setIsMobileOpen] = useState(false); 
 
  const handleLogin = (userData) => { 
    setCurrentUser(userData); 
    setIsLoggedIn(true); 
  }; 
 
  const handleLogout = () => { 
    setIsLoggedIn(false); 
    setCurrentUser(null); 
    setCurrentPage('dashboard'); 
  }; 
 
  if (!isLoggedIn) { 
    return <LoginPage onLoginSuccess={handleLogin} />; 
  } 
 
  return ( 
    <div className="flex h-screen bg-gradient-to-br from-gray-50 to-gray-100 overflow-hidden"> 
      <Sidebar 
        currentPage={currentPage} 
        setCurrentPage={setCurrentPage} 
        isMobileOpen={isMobileOpen} 
        setIsMobileOpen={setIsMobileOpen} 
        currentUser={currentUser} 
      /> 
 
      <div className="flex-1 flex flex-col overflow-hidden"> 
        <TopBar 
          onLogout={handleLogout} 
          setIsMobileOpen={setIsMobileOpen} 
          currentUser={currentUser} 
        /> 
 
        <main className="flex-1 overflow-y-auto"> 
          {currentPage === 'dashboard' && <DashboardPage user={currentUser} />} 
          {currentPage === 'inventory' && <StockManagement />} 
          {currentPage === 'stock-management' && <StockManagement />} 
          {currentPage === 'sales-history' && <SalesHistory />}
          {currentPage === 'customers' && <CustomerManagement />}
          {currentPage === 'products' && <ProductManagement />}
          {currentPage === 'billing' && <BillingManagement />} 
          {currentPage === 'orders' && <OrdersManagement />}
          {currentPage === 'reports' && <Reports />}
          {currentPage === 'payments' && <PaymentPage/>} 
          {currentPage === 'notifications' && <NotificationsPage/>}
          {currentPage === 'discounts' &&<DiscountManagement/>}
          {currentPage === 'coupons' && <CouponManagement />}
          {currentPage === 'gst' && <TaxManagement />}
          {currentPage === 'expenses' && <Expense />}
          {currentPage === 'ledger' && <CoinBillingSystem />}

          {currentPage === 'gst' && ( 
            <div className="p-6"> 
               
            </div> 
          )} 
        </main> 
      </div> 
    </div> 
  ); 
} 
 
export default App;