import {
  ArrowDownCircle,
  ArrowUpCircle,
  Coins,
  Crown,
  Edit,
  Gem,
  Gift,
  History,
  Percent,
  Phone,
  Plus,
  RefreshCw,
  Search,
  ShoppingBag,
  Users,
  X
} from 'lucide-react';
import { useCallback, useEffect, useMemo, useState } from 'react';

const SupermarketCoinWallet = () => {
  // State management
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedFilter, setSelectedFilter] = useState('all');
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [showTxModal, setShowTxModal] = useState(false);
  const [showAddCoinsModal, setShowAddCoinsModal] = useState(false);
  const [showRedeemModal, setShowRedeemModal] = useState(false);
  const [showTierModal, setShowTierModal] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [txData, setTxData] = useState({ type: 'Manual Credit', amount: '', note: '' });
  const [redeemAmount, setRedeemAmount] = useState('');
  const [newTier, setNewTier] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Customer data - initially empty, will be fetched from API
  const [customers, setCustomers] = useState([]);

  // Coin conversion rates
  const coinRates = {
    earnedPer100: 10,
    redeemValuePerCoin: 0.50,
    minimumRedeem: 100,
    maxRedeemPercent: 20
  };

  // Stats calculation
  const [stats, setStats] = useState({
    totalCustomers: 0,
    totalCoins: 0,
    coinsValue: 0,
    todayEarned: 0,
    todayRedeemed: 0,
    activeCustomers: 0
  });

  // API Base URL - FIXED: Your backend runs on port 5000
  const API_BASE_URL = 'http://localhost:5000/api';

  // Fetch customers from backend - UPDATED to match your route
  const fetchCustomers = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await fetch(`${API_BASE_URL}/customers`);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const data = await response.json();
      // Your backend returns { success, count, customers }
      setCustomers(data.customers || []);
    } catch (error) {
      console.error('Error fetching customers:', error);
      setError('Failed to load customer data. Please check your backend connection.');
      // Fallback to sample data if API fails
      setCustomers(getSampleCustomers());
    } finally {
      setLoading(false);
    }
  }, []);

  // Update customer via API - UPDATED to match your route
  const updateCustomer = async (customerId, updates) => {
    try {
      // Note: customerId is the MongoDB _id, not customerId field
      const response = await fetch(`${API_BASE_URL}/customers/${customerId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(updates)
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to update customer');
      }

      return await response.json();
    } catch (error) {
      console.error('Error updating customer:', error);
      throw error;
    }
  };

  // Create transaction via API - NEW: Using your coin adjustment endpoint
  const createTransaction = async (transactionData) => {
    try {
      const response = await fetch(`${API_BASE_URL}/customers/${transactionData.customerId}/coins`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          type: transactionData.type,
          coins: transactionData.amount,
          note: transactionData.note
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to create transaction');
      }

      return await response.json();
    } catch (error) {
      console.error('Error creating transaction:', error);
      throw error;
    }
  };

  // Fetch customer history - UPDATED to match your route
  const fetchCustomerHistory = async (customerId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/customers/${customerId}/transactions?limit=50`);
      
      if (!response.ok) {
        throw new Error('Failed to fetch transaction history');
      }
      
      const data = await response.json();
      return data.transactions || [];
    } catch (error) {
      console.error('Error fetching history:', error);
      return [];
    }
  };

  // Initialize data
  useEffect(() => {
    fetchCustomers();
  }, [fetchCustomers]);

  // Update stats when customers change
  useEffect(() => {
    const totalCoins = customers.reduce((sum, customer) => sum + (customer.coins || 0), 0);
    const coinsValue = totalCoins * coinRates.redeemValuePerCoin;
    
    // For today's stats, we'd normally fetch from API
    // For now, we'll calculate from the data we have
    const today = new Date().toISOString().split('T')[0];
    const todayEarned = 0; // Would need to calculate from transactions
    const todayRedeemed = 0; // Would need to calculate from transactions
    
    const activeCustomers = customers.filter(c => c.status === 'active').length;

    setStats({
      totalCustomers: customers.length,
      totalCoins,
      coinsValue,
      todayEarned,
      todayRedeemed,
      activeCustomers
    });
  }, [customers, coinRates.redeemValuePerCoin]);

  // Handle manual coin transaction - UPDATED to match your API
  const handleCoinTransaction = async (e) => {
    e.preventDefault();
    const amount = parseInt(txData.amount);
    
    if (!selectedCustomer || !amount || amount <= 0) return;

    try {
      // Create transaction using your coin adjustment endpoint
      const result = await createTransaction({
        customerId: selectedCustomer._id, // Use MongoDB _id
        type: txData.type,
        amount: amount,
        note: txData.note
      });

      // Update local state with the updated customer from response
      setCustomers(customers.map(c => 
        c._id === selectedCustomer._id ? result.customer : c
      ));
      
      // Update selected customer in modal
      if (showTxModal) {
        setSelectedCustomer(result.customer);
      }
      
      setShowTxModal(false);
      setTxData({ type: 'Manual Credit', amount: '', note: '' });
      alert('Transaction completed successfully!');
      
    } catch (error) {
      alert(`Failed to process transaction: ${error.message}`);
    }
  };

  // Handle coin redemption - UPDATED to match your API
  const handleRedeemCoins = async (e) => {
    e.preventDefault();
    const amount = parseInt(redeemAmount);
    
    if (!selectedCustomer || !amount || amount <= 0 || 
        amount > selectedCustomer.coins || 
        amount < coinRates.minimumRedeem) {
      alert(`Invalid redemption amount. Minimum: ${coinRates.minimumRedeem}, Available: ${selectedCustomer.coins}`);
      return;
    }

    try {
      const response = await fetch(`${API_BASE_URL}/customers/${selectedCustomer._id}/redeem`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          coins: amount,
          note: `Redeemed ${amount} coins`
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to redeem coins');
      }

      const result = await response.json();
      
      // Update local state
      setCustomers(customers.map(c => 
        c._id === selectedCustomer._id ? result.customer : c
      ));
      
      setShowRedeemModal(false);
      setRedeemAmount('');
      alert(`Successfully redeemed ${amount} coins for ₹${result.transaction.discountValue} discount!`);
      
    } catch (error) {
      alert(`Failed to process redemption: ${error.message}`);
    }
  };

  // Add coins from purchase - UPDATED to match your API
  const handleAddPurchaseCoins = async (purchaseAmount) => {
    if (!selectedCustomer) return;
    
    try {
      const response = await fetch(`${API_BASE_URL}/customers/${selectedCustomer._id}/purchase`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          purchaseAmount: purchaseAmount,
          note: `Purchase: ₹${purchaseAmount}`
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to record purchase');
      }

      const result = await response.json();
      
      // Update local state
      setCustomers(customers.map(c => 
        c._id === selectedCustomer._id ? result.customer : c
      ));
      
      setShowAddCoinsModal(false);
      alert(result.message);
      
    } catch (error) {
      alert(`Failed to add purchase: ${error.message}`);
    }
  };

  // Handle tier change - UPDATED
  const handleTierChange = async (e) => {
    e.preventDefault();
    
    if (!selectedCustomer || !newTier) return;

    try {
      const updatedCustomer = await updateCustomer(selectedCustomer._id, {
        membershipTier: newTier
      });

      // Update local state
      setCustomers(customers.map(c => 
        c._id === selectedCustomer._id ? updatedCustomer.customer : c
      ));
      
      setShowTierModal(false);
      setNewTier('');
      alert(`Tier updated to ${newTier} successfully!`);
      
    } catch (error) {
      alert(`Failed to update tier: ${error.message}`);
    }
  };

  // Filter customers
  const filteredCustomers = useMemo(() => {
    let filtered = customers.filter(c => 
      c.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.phone?.includes(searchTerm) ||
      c.customerId?.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (selectedFilter !== 'all') {
      filtered = filtered.filter(c => c.membershipTier === selectedFilter);
    }

    return filtered;
  }, [customers, searchTerm, selectedFilter]);

  // Get tier color
  const getTierColor = (tier) => {
    switch(tier) {
      case 'Platinum': return 'bg-gradient-to-r from-gray-800 to-gray-600 text-white';
      case 'Gold': return 'bg-gradient-to-r from-yellow-500 to-yellow-400 text-yellow-900';
      case 'Silver': return 'bg-gradient-to-r from-gray-400 to-gray-300 text-gray-800';
      case 'Bronze': return 'bg-gradient-to-r from-amber-800 to-amber-600 text-amber-100';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  // Get tier icon
  const getTierIcon = (tier) => {
    switch(tier) {
      case 'Platinum': return <Crown size={12} className="inline mr-1" />;
      case 'Gold': return <Gem size={12} className="inline mr-1" />;
      case 'Silver': return <Coins size={12} className="inline mr-1" />;
      case 'Bronze': return <Gift size={12} className="inline mr-1" />;
      default: return null;
    }
  };

  // Calculate tier automatically based on purchases
  const calculateAutoTier = (purchases = 0) => {
    if (purchases >= 5000) return 'Platinum';
    if (purchases >= 2000) return 'Gold';
    if (purchases >= 500) return 'Silver';
    return 'Bronze';
  };

  // Sample data for fallback
  const getSampleCustomers = () => [
    {
      _id: '1',
      customerId: 'CUST001',
      name: 'Rohan Sharma',
      phone: '+91 9876543210',
      totalPurchases: 2450.75,
      visitCount: 12,
      membershipTier: 'Gold',
      coins: 450,
      joinDate: '2023-10-15',
      lastVisit: '2023-12-10',
      status: 'active',
      totalSpent: 2450.75
    },
    {
      _id: '2',
      customerId: 'CUST002',
      name: 'Aisha Khan',
      phone: '+91 9876543211',
      totalPurchases: 1250.50,
      visitCount: 8,
      membershipTier: 'Silver',
      coins: 120,
      joinDate: '2023-11-20',
      lastVisit: '2023-12-09',
      status: 'active',
      totalSpent: 1250.50
    },
    {
      _id: '3',
      customerId: 'CUST003',
      name: 'Arun Patel',
      phone: '+91 9876543212',
      totalPurchases: 5500.25,
      visitCount: 25,
      membershipTier: 'Platinum',
      coins: 1200,
      joinDate: '2023-09-05',
      lastVisit: '2023-12-10',
      status: 'active',
      totalSpent: 5500.25
    }
  ];

  // Handle viewing history - UPDATED
  const handleViewHistory = async (customer) => {
    setSelectedCustomer(customer);
    try {
      const history = await fetchCustomerHistory(customer._id);
      setSelectedCustomer({
        ...customer,
        history: history.map(tx => ({
          id: tx._id,
          date: new Date(tx.createdAt).toISOString().split('T')[0],
          type: tx.type,
          amount: tx.coins || 0,
          note: tx.note,
          balance: tx.balanceAfter
        }))
      });
      setShowHistoryModal(true);
    } catch (error) {
      console.error('Error loading history:', error);
      setSelectedCustomer(customer);
      setShowHistoryModal(true);
    }
  };

  return (
    <div className="p-4 md:p-6 bg-gray-50 min-h-screen font-sans"> {/* Changed background to grey like in the image */}
      {/* Inline CSS styles */}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        
        @keyframes slideUp {
          from { 
            opacity: 0;
            transform: translateY(20px);
          }
          to { 
            opacity: 1;
            transform: translateY(0);
          }
        }
        
        .animate-fadeIn {
          animation: fadeIn 0.2s ease-out;
        }
        
        .animate-slideUp {
          animation: slideUp 0.3s ease-out;
        }
        
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
        }
        
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f1f1;
          border-radius: 10px;
        }
        
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #c1c1c1;
          border-radius: 10px;
        }
        
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #a8a8a8;
        }
      `}</style>

      {/* Header with Stats */}
      <div className="max-w-7xl mx-auto mb-8">
  <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 mb-8">
    <div>
      <h1 className="text-3xl md:text-4xl font-bold text-gray-800 flex items-center gap-3">
        {/* Green rounded-square icon */}
        <div className="p-3 rounded-2xl shadow-lg bg-[#1DBF73]">
          <Coins className="text-white" size={28} />
        </div>
              <span>Super Wallet Loyalty</span>
            </h1>
            <p className="text-gray-600 mt-2 text-sm">Manage customer coins and rewards system</p>
          </div>
          
          <div className="flex flex-wrap gap-3">
            <div className="bg-white px-4 py-2 rounded-xl border border-gray-200 shadow-sm">
              <div className="text-xs text-gray-500 font-medium">Exchange Rate</div>
              <div className="font-bold text-blue-600">1 Coin = ₹{coinRates.redeemValuePerCoin}</div>
            </div>
            <div className="bg-white px-4 py-2 rounded-xl border border-gray-200 shadow-sm">
              <div className="text-xs text-gray-500 font-medium">Earning Rate</div>
              <div className="font-bold text-blue-600">₹100 = {coinRates.earnedPer100} coins</div>
            </div>
            <button 
              onClick={fetchCustomers}
              className="bg-white px-4 py-2 rounded-xl border border-gray-200 shadow-sm hover:bg-gray-50 transition flex items-center gap-2"
            >
              <RefreshCw size={16} />
              Refresh
            </button>
          </div>
        </div>

        {/* Stats Dashboard */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
          <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
            <div className="flex justify-between items-start">
              <div>
                <p className="text-sm text-gray-500 font-medium">Total Coins</p>
                <p className="text-3xl font-bold text-green-600 mt-2">{stats.totalCoins.toLocaleString()}</p>
                <p className="text-sm text-gray-500 mt-1">≈ ₹{stats.coinsValue.toFixed(2)} value</p>
              </div>
              <Coins className="text-green-500" size={24} />
            </div>
          </div>

          <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
            <div className="flex justify-between items-start">
              <div>
                <p className="text-sm text-gray-500 font-medium">Active Customers</p>
                <p className="text-3xl font-bold text-blue-600 mt-2">{stats.activeCustomers}</p>
                <p className="text-sm text-gray-500 mt-1">of {stats.totalCustomers} total</p>
              </div>
              <Users className="text-blue-500" size={24} />
            </div>
          </div>

          <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
            <div className="flex justify-between items-start">
              <div>
                <p className="text-sm text-gray-500 font-medium">Today Earned</p>
                <p className="text-3xl font-bold text-green-600 mt-2">{stats.todayEarned}</p>
                <p className="text-sm text-gray-500 mt-1">coins issued</p>
              </div>
              <ArrowUpCircle className="text-green-500" size={24} />
            </div>
          </div>

          <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
            <div className="flex justify-between items-start">
              <div>
                <p className="text-sm text-gray-500 font-medium">Today Redeemed</p>
                <p className="text-3xl font-bold text-orange-600 mt-2">{stats.todayRedeemed}</p>
                <p className="text-sm text-gray-500 mt-1">coins used</p>
              </div>
              <ArrowDownCircle className="text-orange-500" size={24} />
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto">
        {/* Control Bar */}
        <div className="mb-6 flex flex-col md:flex-row gap-4 justify-between items-center">
          <div className="relative w-full md:w-auto">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input 
              type="text" 
              placeholder="Search by name, phone, or customer ID..."
              className="pl-12 pr-4 py-3 bg-white border border-gray-200 rounded-xl w-full md:w-96 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent shadow-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex flex-wrap gap-2 w-full md:w-auto">
            <button 
              onClick={() => setSelectedFilter('all')}
              className={`px-4 py-2 rounded-lg font-medium text-sm transition ${selectedFilter === 'all' ? 'bg-blue-600 text-white' : 'bg-white text-gray-600 hover:bg-gray-50'}`}
            >
              All
            </button>
            <button 
              onClick={() => setSelectedFilter('Platinum')}
              className={`px-4 py-2 rounded-lg font-medium text-sm transition ${selectedFilter === 'Platinum' ? 'bg-gradient-to-r from-gray-800 to-gray-600 text-white' : 'bg-white text-gray-600 hover:bg-gray-50'}`}
            >
              Platinum
            </button>
            <button 
              onClick={() => setSelectedFilter('Gold')}
              className={`px-4 py-2 rounded-lg font-medium text-sm transition ${selectedFilter === 'Gold' ? 'bg-gradient-to-r from-yellow-500 to-yellow-400 text-yellow-900' : 'bg-white text-gray-600 hover:bg-gray-50'}`}
            >
              Gold
            </button>
            <button 
              onClick={() => setSelectedFilter('Silver')}
              className={`px-4 py-2 rounded-lg font-medium text-sm transition ${selectedFilter === 'Silver' ? 'bg-gradient-to-r from-gray-400 to-gray-300 text-gray-800' : 'bg-white text-gray-600 hover:bg-gray-50'}`}
            >
              Silver
            </button>
            <button 
              onClick={() => setSelectedFilter('Bronze')}
              className={`px-4 py-2 rounded-lg font-medium text-sm transition ${selectedFilter === 'Bronze' ? 'bg-gradient-to-r from-amber-800 to-amber-600 text-amber-100' : 'bg-white text-gray-600 hover:bg-gray-50'}`}
            >
              Bronze
            </button>
          </div>
        </div>

        {/* Loading and Error States */}
        {loading && (
          <div className="text-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
            <p className="mt-4 text-gray-600">Loading customer data...</p>
          </div>
        )}

        {error && !loading && (
          <div className="bg-red-50 border border-red-200 rounded-xl p-4 mb-6">
            <p className="text-red-600 font-medium">{error}</p>
            <p className="text-sm text-red-500 mt-1">Using sample data for demonstration</p>
          </div>
        )}

        {/* Customers List/Table */}
        {!loading && (
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-100">
                  <tr>
                    <th className="text-left p-4 text-sm font-bold text-gray-500 uppercase">Customer</th>
                    <th className="text-left p-4 text-sm font-bold text-gray-500 uppercase">Customer ID</th>
                    <th className="text-left p-4 text-sm font-bold text-gray-500 uppercase">Tier</th>
                    <th className="text-left p-4 text-sm font-bold text-gray-500 uppercase">Coin Balance</th>
                    <th className="text-left p-4 text-sm font-bold text-gray-500 uppercase">Status</th>
                    <th className="text-left p-4 text-sm font-bold text-gray-500 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredCustomers.map(customer => (
                    <tr key={customer._id} className="border-b border-gray-50 hover:bg-gray-50/50 transition">
                      <td className="p-4">
                        <div className="flex items-center gap-3">
                          <div className="h-10 w-10 rounded-full bg-gradient-to-r from-blue-400 to-green-400 flex items-center justify-center text-white font-bold">
                            {customer.name?.charAt(0) || 'C'}
                          </div>
                          <div>
                            <h3 className="font-bold text-gray-800">{customer.name}</h3>
                            <div className="text-sm text-gray-500">
                              <span className="flex items-center gap-1">
                                <Phone size={12} /> {customer.phone}
                              </span>
                            </div>
                          </div>
                        </div>
                      </td>
                      <td className="p-4">
                        <div className="font-mono text-sm font-medium text-gray-600 bg-gray-50 px-2 py-1 rounded">
                          {customer.customerId}
                        </div>
                      </td>
                      <td className="p-4">
                        <div className="flex flex-col gap-2">
                          <span className={`px-3 py-1.5 rounded-full text-xs font-bold flex items-center justify-center w-24 ${getTierColor(customer.membershipTier)}`}>
                            {getTierIcon(customer.membershipTier)}
                            {customer.membershipTier}
                          </span>
                          <button 
                            onClick={() => {
                              setSelectedCustomer(customer);
                              setNewTier(customer.membershipTier);
                              setShowTierModal(true);
                            }}
                            className="text-xs text-blue-600 hover:text-blue-800 flex items-center gap-1"
                          >
                            <Edit size={10} /> Change
                          </button>
                        </div>
                      </td>
                      <td className="p-4">
                        <div className="flex items-center gap-2">
                          <div className="text-2xl font-bold text-green-600">{(customer.coins || 0).toLocaleString()}</div>
                          <Gem size={16} className="text-yellow-500" />
                        </div>
                        <div className="text-xs text-gray-500">
                          ≈ ₹{((customer.coins || 0) * coinRates.redeemValuePerCoin).toFixed(2)}
                        </div>
                      </td>
                  
                      <td className="p-4">
                        <div className="flex items-center gap-2">
                          <div className={`h-2 w-2 rounded-full ${customer.status === 'active' ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                          <span className="text-sm font-medium capitalize">{customer.status || 'active'}</span>
                        </div>
                      </td>
                      <td className="p-4">
                        <div className="flex items-center gap-2">
                          <button 
                            onClick={() => { setSelectedCustomer(customer); setShowAddCoinsModal(true); }}
                            className="p-2 bg-blue-50 hover:bg-blue-100 text-blue-600 rounded-lg transition"
                            title="Add Purchase"
                          >
                            <ShoppingBag size={18} />
                          </button>
                          <button 
                            onClick={() => { setSelectedCustomer(customer); setShowRedeemModal(true); }}
                            className="p-2 bg-green-50 hover:bg-green-100 text-green-600 rounded-lg transition"
                            title="Redeem Coins"
                            disabled={(customer.coins || 0) < coinRates.minimumRedeem}
                          >
                            <Percent size={18} />
                          </button>
                          <button 
                            onClick={() => { 
                              setSelectedCustomer(customer); 
                              setTxData({type: 'Manual Credit', amount: '', note: ''}); 
                              setShowTxModal(true); 
                            }}
                            className="p-2 bg-gray-50 hover:bg-gray-100 text-gray-600 rounded-lg transition"
                            title="Add Coins"
                          >
                            <Plus size={18} />
                          </button>
                          <button 
                            onClick={() => handleViewHistory(customer)}
                            className="p-2 bg-gray-50 hover:bg-gray-100 text-gray-600 rounded-lg transition"
                            title="View History"
                          >
                            <History size={18} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            
            {filteredCustomers.length === 0 && !loading && (
              <div className="text-center py-12">
                <div className="text-gray-300 mb-4">
                  <Users size={64} className="mx-auto" />
                </div>
                <h3 className="text-lg font-bold text-gray-400">No customers found</h3>
                <p className="text-gray-500 mt-1">Try adjusting your search or filter</p>
              </div>
            )}
          </div>
        )}

        {/* Summary Footer */}
        {!loading && (
          <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-500 font-medium">Showing</p>
                  <p className="text-lg font-bold text-gray-800">{filteredCustomers.length} customers</p>
                </div>
                <div className="text-right">
                  <p className="text-sm text-gray-500">Total Coins</p>
                  <p className="text-xl font-bold text-green-600">
                    {filteredCustomers.reduce((sum, c) => sum + (c.coins || 0), 0).toLocaleString()}
                  </p>
                </div>
              </div>
            </div>
            
            <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-500 font-medium">Average Coins</p>
                  <p className="text-lg font-bold text-gray-800">
                    {filteredCustomers.length > 0 
                      ? Math.round(filteredCustomers.reduce((sum, c) => sum + (c.coins || 0), 0) / filteredCustomers.length).toLocaleString()
                      : '0'}
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-sm text-gray-500">Total Value</p>
                  <p className="text-xl font-bold text-green-600">
                    ₹{(filteredCustomers.reduce((sum, c) => sum + (c.coins || 0), 0) * coinRates.redeemValuePerCoin).toFixed(2)}
                  </p>
                </div>
              </div>
            </div>
            
            <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-500 font-medium">Eligible for Redeem</p>
                  <p className="text-lg font-bold text-gray-800">
                    {filteredCustomers.filter(c => (c.coins || 0) >= coinRates.minimumRedeem).length} customers
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-sm text-gray-500">Inactive</p>
                  <p className="text-xl font-bold text-gray-400">
                    {filteredCustomers.filter(c => c.status === 'inactive').length}
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* MODAL: MANUAL COIN TRANSACTION */}
      {showTxModal && selectedCustomer && (
        <Modal onClose={() => setShowTxModal(false)} title={txData.type === 'Manual Credit' ? 'Add Coins' : 'Deduct Coins'}>
          <form onSubmit={handleCoinTransaction} className="space-y-6">
            <div className="p-5 bg-gradient-to-r from-blue-50 to-green-50 rounded-2xl border border-green-100">
              <p className="text-xs font-bold text-green-800 uppercase mb-1">Customer</p>
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-lg font-bold text-gray-800">{selectedCustomer.name}</p>
                  <p className="text-sm text-gray-500">ID: {selectedCustomer.customerId}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs text-gray-500">Current Balance</p>
                  <p className="text-2xl font-bold text-green-600">{(selectedCustomer.coins || 0).toLocaleString()} <Gem size={16} className="inline" /></p>
                </div>
              </div>
            </div>
            
            <div className="flex gap-4 mb-4">
              <button
                type="button"
                onClick={() => setTxData({...txData, type: 'Manual Credit'})}
                className={`flex-1 py-3 rounded-xl font-bold transition ${txData.type === 'Manual Credit' ? 'bg-green-100 text-green-700 border-2 border-green-300' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
              >
                Add Coins
              </button>
              <button
                type="button"
                onClick={() => setTxData({...txData, type: 'Manual Debit'})}
                className={`flex-1 py-3 rounded-xl font-bold transition ${txData.type === 'Manual Debit' ? 'bg-red-100 text-red-700 border-2 border-red-300' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
              >
                Deduct Coins
              </button>
            </div>
            
            <div>
              <label className="text-xs font-bold text-gray-400 uppercase ml-1">Amount</label>
              <div className="relative">
                <input 
                  type="number" 
                  placeholder="0" 
                  autoFocus
                  required 
                  min="1"
                  max={txData.type === 'Manual Debit' ? selectedCustomer.coins : 100000}
                  className="w-full border-2 border-gray-100 p-5 rounded-2xl text-4xl font-bold text-center text-green-600 outline-none focus:border-green-500 transition pr-20" 
                  value={txData.amount} 
                  onChange={(e) => setTxData({...txData, amount: e.target.value})} 
                />
                <div className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">COINS</div>
              </div>
              {txData.type === 'Manual Debit' && (
                <p className="text-xs text-red-500 mt-2 text-center">
                  Maximum deduction: {selectedCustomer.coins} coins
                </p>
              )}
            </div>
            
            <div>
              <label className="text-xs font-bold text-gray-400 uppercase ml-1 mb-2 block">Transaction Note</label>
              <textarea 
                placeholder="Add a description for this transaction..."
                required 
                rows="3"
                className="w-full border-2 border-gray-100 p-4 rounded-xl outline-none focus:border-green-500 transition resize-none" 
                value={txData.note} 
                onChange={(e) => setTxData({...txData, note: e.target.value})} 
              />
            </div>
            
            <div className="grid grid-cols-2 gap-3">
              <button 
                type="button"
                onClick={() => setShowTxModal(false)}
                className="py-4 rounded-xl font-bold text-gray-600 bg-gray-100 hover:bg-gray-200 transition"
              >
                Cancel
              </button>
              <button 
                type="submit"
                className={`py-4 rounded-xl font-bold text-white shadow-lg transition ${txData.type === 'Manual Credit' ? 'bg-gradient-to-r from-green-600 to-green-500 hover:opacity-90' : 'bg-gradient-to-r from-red-600 to-orange-600 hover:opacity-90'}`}
              >
                {txData.type === 'Manual Credit' ? 'ADD COINS' : 'DEDUCT COINS'}
              </button>
            </div>
          </form>
        </Modal>
      )}

      {/* MODAL: ADD COINS FROM PURCHASE */}
      {showAddCoinsModal && selectedCustomer && (
        <Modal onClose={() => setShowAddCoinsModal(false)} title="Add Coins from Purchase">
          <form onSubmit={(e) => {
            e.preventDefault();
            const purchaseAmount = parseFloat(e.target.purchaseAmount.value);
            if (purchaseAmount > 0) {
              handleAddPurchaseCoins(purchaseAmount);
            }
          }} className="space-y-6">
            <div className="p-5 bg-gradient-to-r from-blue-50 to-green-50 rounded-2xl border border-green-100">
              <p className="text-xs font-bold text-green-800 uppercase mb-1">Customer</p>
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-lg font-bold text-gray-800">{selectedCustomer.name}</p>
                  <p className="text-sm text-gray-500">ID: {selectedCustomer.customerId}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs text-gray-500">Current Balance</p>
                  <p className="text-2xl font-bold text-green-600">{(selectedCustomer.coins || 0).toLocaleString()} <Gem size={16} className="inline" /></p>
                </div>
              </div>
            </div>
            
            <div>
              <label className="text-xs font-bold text-gray-400 uppercase ml-1">Purchase Amount (₹)</label>
              <div className="relative">
                <input 
                  type="number" 
                  name="purchaseAmount"
                  placeholder="0.00" 
                  autoFocus
                  required 
                  min="0.01"
                  step="0.01"
                  className="w-full border-2 border-gray-100 p-5 rounded-2xl text-4xl font-bold text-center text-blue-600 outline-none focus:border-blue-500 transition pr-20" 
                />
                <div className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">₹</div>
              </div>
              <p className="text-xs text-gray-500 mt-2 text-center">
                Earn coins based on tier: Bronze=10/₹100, Silver=11/₹100, Gold=12/₹100, Platinum=13/₹100
              </p>
            </div>
            
            <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
              <div className="flex justify-between items-center">
                <span className="text-sm text-gray-700">Estimated coins to earn:</span>
                <span className="font-bold text-green-600">
                  {(() => {
                    const purchaseAmount = parseFloat(document.querySelector('input[name="purchaseAmount"]')?.value || 0);
                    const rates = { Bronze: 10, Silver: 11, Gold: 12, Platinum: 13 };
                    const rate = rates[selectedCustomer.membershipTier] || 10;
                    return Math.floor(purchaseAmount / 100 * rate);
                  })()}
                </span>
              </div>
            </div>
            
            <div className="grid grid-cols-2 gap-3">
              <button 
                type="button"
                onClick={() => setShowAddCoinsModal(false)}
                className="py-4 rounded-xl font-bold text-gray-600 bg-gray-100 hover:bg-gray-200 transition"
              >
                Cancel
              </button>
              <button 
                type="submit"
                className="py-4 rounded-xl font-bold text-white bg-gradient-to-r from-blue-600 to-green-600 hover:opacity-90 transition shadow-md"
              >
                ADD PURCHASE
              </button>
            </div>
          </form>
        </Modal>
      )}

      {/* MODAL: REDEEM COINS */}
      {showRedeemModal && selectedCustomer && (
        <Modal onClose={() => setShowRedeemModal(false)} title="Redeem Coins">
          <form onSubmit={handleRedeemCoins} className="space-y-6">
            <div className="p-5 bg-gradient-to-r from-yellow-50 to-orange-50 rounded-2xl border border-yellow-100">
              <p className="text-xs font-bold text-yellow-800 uppercase mb-1">Customer</p>
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-lg font-bold text-gray-800">{selectedCustomer.name}</p>
                  <p className="text-sm text-gray-500">ID: {selectedCustomer.customerId}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs text-gray-500">Current Balance</p>
                  <p className="text-2xl font-bold text-green-600">{(selectedCustomer.coins || 0).toLocaleString()} <Gem size={16} className="inline" /></p>
                </div>
              </div>
            </div>
            
            <div>
              <label className="text-xs font-bold text-gray-400 uppercase ml-1">Coins to Redeem</label>
              <div className="relative">
                <input 
                  type="number" 
                  placeholder="0" 
                  autoFocus
                  required 
                  min={coinRates.minimumRedeem}
                  max={selectedCustomer.coins}
                  className="w-full border-2 border-gray-100 p-5 rounded-2xl text-4xl font-bold text-center text-yellow-600 outline-none focus:border-yellow-500 transition pr-20" 
                  value={redeemAmount} 
                  onChange={(e) => setRedeemAmount(e.target.value)} 
                />
                <div className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">COINS</div>
              </div>
              <p className="text-xs text-gray-500 mt-2 text-center">
                Minimum: {coinRates.minimumRedeem} coins
              </p>
            </div>
            
            <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100">
              <div className="flex justify-between items-center mb-2">
                <span className="text-sm text-gray-700">Discount Value:</span>
                <span className="font-bold text-green-600 text-xl">
                  ₹{((redeemAmount || 0) * coinRates.redeemValuePerCoin).toFixed(2)}
                </span>
              </div>
              <p className="text-xs text-gray-500">
                Exchange rate: 1 coin = ₹{coinRates.redeemValuePerCoin}
              </p>
            </div>
            
            <div className="grid grid-cols-2 gap-3">
              <button 
                type="button"
                onClick={() => setShowRedeemModal(false)}
                className="py-4 rounded-xl font-bold text-gray-600 bg-gray-100 hover:bg-gray-200 transition"
              >
                Cancel
              </button>
              <button 
                type="submit"
                disabled={!redeemAmount || parseInt(redeemAmount) < coinRates.minimumRedeem || parseInt(redeemAmount) > (selectedCustomer.coins || 0)}
                className="py-4 rounded-xl font-bold text-white bg-gradient-to-r from-yellow-600 to-orange-600 hover:opacity-90 transition shadow-md disabled:opacity-50 disabled:cursor-not-allowed"
              >
                APPLY DISCOUNT
              </button>
            </div>
          </form>
        </Modal>
      )}

      {/* MODAL: CHANGE TIER */}
      {showTierModal && selectedCustomer && (
        <Modal onClose={() => setShowTierModal(false)} title="Change Membership Tier">
          <form onSubmit={handleTierChange} className="space-y-6">
            <div className="p-5 bg-gradient-to-r from-purple-50 to-pink-50 rounded-2xl border border-purple-100">
              <p className="text-xs font-bold text-purple-800 uppercase mb-1">Customer</p>
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-lg font-bold text-gray-800">{selectedCustomer.name}</p>
                  <p className="text-sm text-gray-500">ID: {selectedCustomer.customerId}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs text-gray-500">Current Tier</p>
                  <p className={`text-xl font-bold px-3 py-1 rounded-full ${getTierColor(selectedCustomer.membershipTier)}`}>
                    {selectedCustomer.membershipTier}
                  </p>
                </div>
              </div>
            </div>
            
            <div>
              <label className="text-xs font-bold text-gray-400 uppercase ml-1 mb-2 block">Select New Tier</label>
              <div className="grid grid-cols-2 gap-3">
                {['Platinum', 'Gold', 'Silver', 'Bronze'].map(tier => (
                  <button
                    key={tier}
                    type="button"
                    onClick={() => setNewTier(tier)}
                    className={`p-4 rounded-xl border-2 transition ${newTier === tier ? 'border-purple-500' : 'border-gray-100'} ${getTierColor(tier)} flex flex-col items-center`}
                  >
                    <span className="font-bold">{tier}</span>
                    <span className="text-xs opacity-90 mt-1">
                      {tier === 'Platinum' && '₹5000+ purchases'}
                      {tier === 'Gold' && '₹2000+ purchases'}
                      {tier === 'Silver' && '₹500+ purchases'}
                      {tier === 'Bronze' && 'New customers'}
                    </span>
                  </button>
                ))}
              </div>
            </div>
            
            <div className="bg-purple-50 p-4 rounded-xl border border-purple-100">
              <div className="flex justify-between items-center">
                <span className="text-sm text-gray-700">Auto-suggested Tier:</span>
                <span className={`font-bold px-3 py-1 rounded-full ${getTierColor(calculateAutoTier(selectedCustomer.totalSpent))}`}>
                  {calculateAutoTier(selectedCustomer.totalSpent)}
                </span>
              </div>
              <p className="text-xs text-gray-500 mt-2">
                Based on ₹{(selectedCustomer.totalSpent || 0).toFixed(2)} total purchases
              </p>
            </div>
            
            <div className="grid grid-cols-2 gap-3">
              <button 
                type="button"
                onClick={() => setShowTierModal(false)}
                className="py-4 rounded-xl font-bold text-gray-600 bg-gray-100 hover:bg-gray-200 transition"
              >
                Cancel
              </button>
              <button 
                type="submit"
                disabled={!newTier || newTier === selectedCustomer.membershipTier}
                className="py-4 rounded-xl font-bold text-white bg-gradient-to-r from-purple-600 to-pink-600 hover:opacity-90 transition shadow-md disabled:opacity-50 disabled:cursor-not-allowed"
              >
                UPDATE TIER
              </button>
            </div>
          </form>
        </Modal>
      )}

      {/* MODAL: TRANSACTION HISTORY */}
      {showHistoryModal && selectedCustomer && (
        <Modal onClose={() => setShowHistoryModal(false)} title="Transaction History" wide>
          <div className="mb-6 p-4 bg-gradient-to-r from-gray-50 to-gray-100 rounded-xl">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="font-bold text-gray-800">{selectedCustomer.name}</h3>
                <p className="text-sm text-gray-500">Customer ID: {selectedCustomer.customerId}</p>
                <p className="text-sm text-gray-500">Current Balance: <span className="font-bold text-green-600">{selectedCustomer.coins || 0} coins</span></p>
              </div>
              <div className="flex items-center gap-2">
              </div>
            </div>
          </div>
          
          <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
            {selectedCustomer.history && selectedCustomer.history.map((tx) => (
              <div key={tx.id} className="flex justify-between items-center p-4 bg-gray-50 rounded-xl border border-gray-100 hover:bg-white transition">
                <div className="flex items-center gap-4">
                  <div className={`p-3 rounded-full ${
                    tx.type === 'Purchase' || tx.type === 'Manual Credit' || tx.type === 'Welcome Bonus' 
                      ? 'bg-green-100 text-green-600' 
                      : 'bg-yellow-100 text-yellow-600'
                  }`}>
                    {tx.type === 'Purchase' || tx.type === 'Manual Credit' || tx.type === 'Welcome Bonus' ? (
                      <ArrowUpCircle size={20}/>
                    ) : (
                      <ArrowDownCircle size={20}/>
                    )}
                  </div>
                  <div>
                    <div className="font-bold text-gray-800">{tx.note}</div>
                    <div className="text-xs text-gray-500 font-medium">{tx.date}</div>
                    <div className="text-xs text-gray-400">{tx.type}</div>
                  </div>
                </div>
                <div className="text-right">
                  <div className={`font-bold text-lg ${
                    tx.type === 'Purchase' || tx.type === 'Manual Credit' || tx.type === 'Welcome Bonus' 
                      ? 'text-green-600' 
                      : 'text-yellow-600'
                  }`}>
                    {tx.type === 'Purchase' || tx.type === 'Manual Credit' || tx.type === 'Welcome Bonus' ? '+' : ''}{tx.amount.toLocaleString()}
                  </div>
                  <div className="text-xs text-gray-500 font-medium">
                    Balance: {tx.balance ? tx.balance.toLocaleString() : 'N/A'}
                  </div>
                </div>
              </div>
            ))}
            
            {(!selectedCustomer.history || selectedCustomer.history.length === 0) && (
              <div className="text-center py-8">
                <History className="mx-auto text-gray-300 mb-3" size={48} />
                <p className="text-gray-500">No transaction history found</p>
              </div>
            )}
          </div>
        </Modal>
      )}

      {/* Info Panel */}
      <div className="max-w-7xl mx-auto mt-8 p-6 bg-white rounded-2xl border border-gray-100 shadow-sm">
        <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
          <InfoIcon size={20} className="text-blue-500" />
          Coin System Rules
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="p-4 bg-blue-50 rounded-xl">
            <h4 className="font-bold text-blue-700 mb-2">Earning Rules</h4>
            <ul className="text-sm text-gray-600 space-y-1">
              <li>• ₹100 spent = 10 coins (Bronze)</li>
              <li>• ₹100 spent = 11 coins (Silver)</li>
              <li>• ₹100 spent = 12 coins (Gold)</li>
              <li>• ₹100 spent = 13 coins (Platinum)</li>
              <li>• Welcome bonus: 50 coins</li>
            </ul>
          </div>
          <div className="p-4 bg-green-50 rounded-xl">
            <h4 className="font-bold text-green-700 mb-2">Redemption Rules</h4>
            <ul className="text-sm text-gray-600 space-y-1">
              <li>• 1 coin = ₹0.50 value</li>
              <li>• Minimum redeem: {coinRates.minimumRedeem} coins</li>
              <li>• Max {coinRates.maxRedeemPercent}% of bill</li>
              <li>• Cannot combine with other offers</li>
            </ul>
          </div>
          <div className="p-4 bg-yellow-50 rounded-xl">
            <h4 className="font-bold text-yellow-700 mb-2">Tier Benefits</h4>
            <ul className="text-sm text-gray-600 space-y-1">
              <li>• Bronze: 10 coins/₹100</li>
              <li>• Silver: 11 coins/₹100 (+10%)</li>
              <li>• Gold: 12 coins/₹100 (+20%)</li>
              <li>• Platinum: 13 coins/₹100 (+30%)</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

// Reusable Modal Component
const Modal = ({ children, onClose, title, wide = false }) => (
  <div className="fixed inset-0 bg-gray-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-fadeIn">
    <div className={`bg-white rounded-2xl p-6 shadow-2xl ${wide ? 'max-w-4xl' : 'max-w-md'} w-full animate-slideUp`}>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-lg font-bold text-gray-800 flex items-center gap-2">
          {title}
        </h2>
        <button 
          onClick={onClose} 
          className="p-2 hover:bg-gray-100 rounded-full transition text-gray-400 hover:text-gray-600"
        >
          <X size={24}/>
        </button>
      </div>
      {children}
    </div>
  </div>
);

// Info Icon Component
const InfoIcon = ({ size = 24 }) => (
  <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="10"></circle>
    <line x1="12" y1="16" x2="12" y2="12"></line>
    <line x1="12" y1="8" x2="12.01" y2="8"></line>
  </svg>
);

export default SupermarketCoinWallet;