import { BarChart3, Calendar, Eye, FileText, Plus, Printer, Search, Trash2, TrendingUp, Wifi, Zap } from 'lucide-react';
import { useEffect, useState } from 'react';

const Expense = () => {
  const [expenses, setExpenses] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [searchField, setSearchField] = useState('description');
  const [showModal, setShowModal] = useState(false);
  const [showReportModal, setShowReportModal] = useState(false);
  const [showViewModal, setShowViewModal] = useState(false);
  const [selectedExpense, setSelectedExpense] = useState(null);
  const [reportType, setReportType] = useState('daily');
  const [loading, setLoading] = useState(false);
  const [newExpense, setNewExpense] = useState({
    date: new Date().toISOString().split('T')[0],
    description: '',
    receivedBy: '',
    category: 'STATIONERY',
    amount: '',
    paymentMode: 'CASH'
  });

  const API_URL = 'http://localhost:5000/api/expenses';

  const categories = {
    RENT: { label: 'Rent', color: 'text-gray-700', bgColor: '#A8E4A0' },
    UTILITY: { label: 'Utility', color: 'text-gray-700', bgColor: '#A8E4A0' },
    STATIONERY: { label: 'Stationery', color: 'text-gray-700', bgColor: '#A8E4A0' },
    SOFTWARE: { label: 'Software', color: 'text-gray-700', bgColor: '#A8E4A0' },
    MAINTENANCE: { label: 'Maintenance', color: 'text-gray-700', bgColor: '#A8E4A0' },
    GENERAL: { label: 'General Expense', color: 'text-gray-700', bgColor: '#A8E4A0' },
    SALARY: { label: 'Staff Salary', color: 'text-gray-700', bgColor: '#FFB4B4' },
    TRANSPORT: { label: 'Transport', color: 'text-gray-700', bgColor: '#B4D4FF' }
  };

  const paymentModes = {
    CASH: { label: 'Cash', color: 'text-green-700', bgColor: '#D4EDDA' },
    UPI: { label: 'UPI', color: 'text-blue-700', bgColor: '#D1ECF1' },
    BANK: { label: 'Bank Transfer', color: 'text-purple-700', bgColor: '#E7D4F5' }
  };

  // Load expenses from backend
  useEffect(() => {
    loadExpenses();
  }, []);

  const loadExpenses = async () => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}?limit=1000&sortBy=date&sortOrder=desc`);
      if (response.ok) {
        const data = await response.json();
        if (data.success) {
          setExpenses(data.data);
        }
      }
    } catch (error) {
      console.error('Error loading expenses:', error);
    } finally {
      setLoading(false);
    }
  };

  const calculateTotals = () => {
    const total = expenses.reduce((sum, exp) => sum + exp.amount, 0);
    const stationery = expenses.filter(e => e.category === 'STATIONERY').reduce((sum, e) => sum + e.amount, 0);
    const software = expenses.filter(e => e.category === 'SOFTWARE').reduce((sum, e) => sum + e.amount, 0);
    const utility = expenses.filter(e => e.category === 'UTILITY').reduce((sum, e) => sum + e.amount, 0);
    const general = expenses.filter(e => e.category === 'GENERAL').reduce((sum, e) => sum + e.amount, 0);
    
    return { total, stationery, software, utility, general };
  };

  const totals = calculateTotals();

  // Generate Reports
  const generateDailyReport = () => {
    const today = new Date().toISOString().split('T')[0];
    return expenses.filter(e => e.date.split('T')[0] === today);
  };

  const generateMonthlyReport = () => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    return expenses.filter(e => {
      const expenseDate = new Date(e.date);
      return expenseDate.getMonth() === currentMonth && expenseDate.getFullYear() === currentYear;
    });
  };

  const generateCategoryReport = () => {
    const categoryTotals = {};
    expenses.forEach(e => {
      if (!categoryTotals[e.category]) {
        categoryTotals[e.category] = 0;
      }
      categoryTotals[e.category] += e.amount;
    });
    return Object.entries(categoryTotals)
      .map(([category, amount]) => ({ category, amount }))
      .sort((a, b) => b.amount - a.amount);
  };

  const getHighestSpendingArea = () => {
    const categoryReport = generateCategoryReport();
    return categoryReport.length > 0 ? categoryReport[0] : null;
  };

  const getReportData = () => {
    switch (reportType) {
      case 'daily':
        return generateDailyReport();
      case 'monthly':
        return generateMonthlyReport();
      case 'category':
        return generateCategoryReport();
      default:
        return [];
    }
  };

  const filteredExpenses = expenses.filter(exp => {
    const searchValue = searchTerm.toLowerCase();
    if (searchField === 'description') {
      return exp.description.toLowerCase().includes(searchValue);
    } else if (searchField === 'category') {
      return exp.category.toLowerCase().includes(searchValue);
    } else if (searchField === 'receivedBy') {
      return exp.receivedBy.toLowerCase().includes(searchValue);
    }
    return true;
  });

  const handleAddExpense = async () => {
    if (newExpense.description && newExpense.amount && newExpense.receivedBy) {
      try {
        const response = await fetch(API_URL, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            ...newExpense,
            amount: parseFloat(newExpense.amount)
          })
        });

        const data = await response.json();
        if (data.success) {
          await loadExpenses(); // Reload expenses
          setNewExpense({
            date: new Date().toISOString().split('T')[0],
            description: '',
            receivedBy: '',
            category: 'STATIONERY',
            amount: '',
            paymentMode: 'CASH'
          });
          setShowModal(false);
        } else {
          alert(data.message || 'Failed to add expense');
        }
      } catch (error) {
        console.error('Error adding expense:', error);
        alert('Failed to add expense');
      }
    }
  };

  const handleDeleteExpense = async (id) => {
    if (window.confirm('Are you sure you want to delete this expense?')) {
      try {
        const response = await fetch(`${API_URL}/${id}`, {
          method: 'DELETE'
        });

        const data = await response.json();
        if (data.success) {
          await loadExpenses(); // Reload expenses
        } else {
          alert(data.message || 'Failed to delete expense');
        }
      } catch (error) {
        console.error('Error deleting expense:', error);
        alert('Failed to delete expense');
      }
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-6">
          <div className="flex items-center gap-2 text-sm font-semibold mb-2" style={{color: '#A8E4A0'}}>
            <span>ADMIN</span>
            <span>•</span>
            <span>EXPENSES</span>
          </div>
          <div className="flex justify-between items-start">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 mb-2">Expense Management</h1>
              <p className="text-gray-600">Track operational spending for billing software business operations</p>
            </div>
            <div className="flex gap-3">
              <button
                onClick={() => setShowReportModal(true)}
                className="bg-blue-600 text-white px-6 py-3 rounded-lg flex items-center gap-2 font-medium transition-colors hover:bg-blue-700"
              >
                <BarChart3 size={20} />
                View Reports
              </button>
              <button
                onClick={() => setShowModal(true)}
                className="text-white px-6 py-3 rounded-lg flex items-center gap-2 font-medium transition-colors hover:opacity-90"
                style={{backgroundColor: '#A8E4A0'}}
              >
                <Plus size={20} />
                Add Expense
              </button>
            </div>
          </div>
        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-200">
            <div className="flex justify-between items-start mb-2">
              <span className="text-gray-600 text-sm font-medium">TOTAL EXPENSES</span>
              <FileText size={20} style={{color: '#A8E4A0'}} />
            </div>
            <div className="text-2xl font-bold text-gray-900">₹{totals.total.toLocaleString('en-IN')}</div>
          </div>
          
          <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-200">
            <div className="flex justify-between items-start mb-2">
              <span className="text-gray-600 text-sm font-medium">STATIONERY</span>
              <Printer size={20} style={{color: '#A8E4A0'}} />
            </div>
            <div className="text-2xl font-bold text-gray-900">₹{totals.stationery.toLocaleString('en-IN')}</div>
          </div>
          
          <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-200">
            <div className="flex justify-between items-start mb-2">
              <span className="text-gray-600 text-sm font-medium">SOFTWARE</span>
              <Wifi size={20} style={{color: '#A8E4A0'}} />
            </div>
            <div className="text-2xl font-bold text-gray-900">₹{totals.software.toLocaleString('en-IN')}</div>
          </div>
          
          <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-200">
            <div className="flex justify-between items-start mb-2">
              <span className="text-gray-600 text-sm font-medium">UTILITY</span>
              <Zap size={20} style={{color: '#A8E4A0'}} />
            </div>
            <div className="text-2xl font-bold text-gray-900">₹{totals.utility.toLocaleString('en-IN')}</div>
          </div>
        </div>

        {/* Highest Spending Alert */}
        {getHighestSpendingArea() && (
          <div className="bg-amber-50 border border-amber-200 rounded-lg p-4 mb-6 flex items-center gap-3">
            <TrendingUp className="text-amber-600" size={24} />
            <div>
              <p className="text-sm font-semibold text-amber-900">Highest Spending Area</p>
              <p className="text-sm text-amber-700">
                <span className="font-bold">{categories[getHighestSpendingArea().category].label}</span> - ₹{getHighestSpendingArea().amount.toLocaleString('en-IN')}
              </p>
            </div>
          </div>
        )}

        {/* Search and Filter */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 mb-4">
          <div className="p-4 flex gap-4">
            <select
              value={searchField}
              onChange={(e) => setSearchField(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#A8E4A0]"
            >
              <option value="description">Select field to search</option>
              <option value="description">Description</option>
              <option value="category">Category</option>
              <option value="receivedBy">Received By</option>
            </select>
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
              <input
                type="text"
                placeholder="Search..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#A8E4A0]"
              />
            </div>
            <span className="text-gray-600 py-2 px-4 bg-gray-50 rounded-lg">
              {filteredExpenses.length} of {expenses.length} rows
            </span>
          </div>
        </div>

        {/* Expense Table */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-gray-600 uppercase tracking-wider">Date</th>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-gray-600 uppercase tracking-wider">Description</th>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-gray-600 uppercase tracking-wider">Category</th>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-gray-600 uppercase tracking-wider">Payment Mode</th>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-gray-600 uppercase tracking-wider">Amount</th>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-gray-600 uppercase tracking-wider">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {loading ? (
                  <tr>
                    <td colSpan="6" className="px-6 py-8 text-center text-gray-500">
                      Loading expenses...
                    </td>
                  </tr>
                ) : filteredExpenses.length === 0 ? (
                  <tr>
                    <td colSpan="6" className="px-6 py-8 text-center text-gray-500">
                      No expenses found
                    </td>
                  </tr>
                ) : (
                  filteredExpenses.map((expense) => (
                    <tr key={expense._id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 text-sm text-gray-900">
                        {new Date(expense.date).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })}
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-sm font-medium text-gray-900">{expense.description}</div>
                        <div className="text-xs text-gray-500">RECEIVED BY {expense.receivedBy.toUpperCase()}</div>
                      </td>
                      <td className="px-6 py-4">
                        <span 
                          className={`inline-flex px-3 py-1 rounded-full text-xs font-medium ${categories[expense.category].color}`}
                          style={{backgroundColor: categories[expense.category].bgColor}}
                        >
                          {categories[expense.category].label.toUpperCase()}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <span 
                          className={`inline-flex px-3 py-1 rounded-full text-xs font-medium ${paymentModes[expense.paymentMode].color}`}
                          style={{backgroundColor: paymentModes[expense.paymentMode].bgColor}}
                        >
                          {paymentModes[expense.paymentMode].label.toUpperCase()}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm font-semibold text-gray-900">₹{expense.amount.toLocaleString('en-IN')}</td>
                      <td className="px-6 py-4">
                        <div className="flex gap-2">
                          <button 
                            onClick={() => {
                              setSelectedExpense(expense);
                              setShowViewModal(true);
                            }}
                            className="p-2 text-gray-400 hover:text-green-600 hover:bg-green-50 rounded-lg transition-colors"
                          >
                            <Eye size={18} />
                          </button>
                          <button
                            onClick={() => handleDeleteExpense(expense._id)}
                            className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                          >
                            <Trash2 size={18} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Add Expense Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h2 className="text-xl font-bold mb-4">Add New Expense</h2>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date *</label>
                <input
                  type="date"
                  value={newExpense.date}
                  onChange={(e) => setNewExpense({ ...newExpense, date: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#A8E4A0]"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Expense Name *</label>
                <input
                  type="text"
                  value={newExpense.description}
                  onChange={(e) => setNewExpense({ ...newExpense, description: e.target.value })}
                  placeholder="e.g., Shop Rent, Electricity Bill, Staff Salary"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#A8E4A0]"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Received By *</label>
                <input
                  type="text"
                  value={newExpense.receivedBy}
                  onChange={(e) => setNewExpense({ ...newExpense, receivedBy: e.target.value })}
                  placeholder="Enter receiver name"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#A8E4A0]"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Category *</label>
                <select
                  value={newExpense.category}
                  onChange={(e) => setNewExpense({ ...newExpense, category: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#A8E4A0]"
                >
                  <option value="RENT">Rent</option>
                  <option value="UTILITY">Utility (Electricity, Water)</option>
                  <option value="SALARY">Staff Salary</option>
                  <option value="TRANSPORT">Transport Charges</option>
                  <option value="STATIONERY">Stationery</option>
                  <option value="SOFTWARE">Software</option>
                  <option value="MAINTENANCE">Maintenance</option>
                  <option value="GENERAL">General Expense</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Payment Mode *</label>
                <select
                  value={newExpense.paymentMode}
                  onChange={(e) => setNewExpense({ ...newExpense, paymentMode: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#A8E4A0]"
                >
                  <option value="CASH">Cash</option>
                  <option value="UPI">UPI</option>
                  <option value="BANK">Bank Transfer</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Amount (₹) *</label>
                <input
                  type="number"
                  value={newExpense.amount}
                  onChange={(e) => setNewExpense({ ...newExpense, amount: e.target.value })}
                  placeholder="Enter amount"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#A8E4A0]"
                />
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <button
                onClick={handleAddExpense}
                className="flex-1 text-white py-2 rounded-lg font-medium transition-colors hover:opacity-90"
                style={{backgroundColor: '#A8E4A0'}}
              >
                Add Expense
              </button>
              <button
                onClick={() => setShowModal(false)}
                className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-800 py-2 rounded-lg font-medium transition-colors"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Reports Modal */}
      {showReportModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg p-6 w-full max-w-4xl max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold">Expense Reports</h2>
              <button
                onClick={() => setShowReportModal(false)}
                className="text-gray-500 hover:text-gray-700"
              >
                ✕
              </button>
            </div>

            <div className="flex gap-2 mb-6">
              <button
                onClick={() => setReportType('daily')}
                className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                  reportType === 'daily' 
                    ? 'bg-[#A8E4A0] text-gray-800' 
                    : 'bg-gray-200 text-gray-600 hover:bg-gray-300'
                }`}
              >
                <Calendar size={16} className="inline mr-2" />
                Daily Expenses
              </button>
              <button
                onClick={() => setReportType('monthly')}
                className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                  reportType === 'monthly' 
                    ? 'bg-[#A8E4A0] text-gray-800' 
                    : 'bg-gray-200 text-gray-600 hover:bg-gray-300'
                }`}
              >
                <Calendar size={16} className="inline mr-2" />
                Monthly Expenses
              </button>
              <button
                onClick={() => setReportType('category')}
                className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                  reportType === 'category' 
                    ? 'bg-[#A8E4A0] text-gray-800' 
                    : 'bg-gray-200 text-gray-600 hover:bg-gray-300'
                }`}
              >
                <BarChart3 size={16} className="inline mr-2" />
                Category-wise
              </button>
            </div>

            <div className="bg-gray-50 rounded-lg p-6">
              {reportType === 'category' ? (
                <div>
                  <h3 className="text-lg font-semibold mb-4">Category-wise Spending</h3>
                  <div className="space-y-3">
                    {getReportData().map((item, index) => (
                      <div key={index} className="bg-white p-4 rounded-lg shadow-sm flex justify-between items-center">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full flex items-center justify-center" style={{backgroundColor: categories[item.category].bgColor}}>
                            <span className="text-xs font-bold">{index + 1}</span>
                          </div>
                          <div>
                            <p className="font-semibold text-gray-900">{categories[item.category].label}</p>
                            <p className="text-xs text-gray-500">
                              {expenses.filter(e => e.category === item.category).length} transactions
                            </p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="text-xl font-bold text-gray-900">₹{item.amount.toLocaleString('en-IN')}</p>
                          <p className="text-xs text-gray-500">
                            {((item.amount / totals.total) * 100).toFixed(1)}% of total
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                <div>
                  <h3 className="text-lg font-semibold mb-4">
                    {reportType === 'daily' ? 'Today\'s Expenses' : 'This Month\'s Expenses'}
                  </h3>
                  <div className="mb-4 bg-blue-50 border border-blue-200 rounded-lg p-4">
                    <p className="text-sm text-blue-700 mb-1">Total Amount</p>
                    <p className="text-2xl font-bold text-blue-900">
                      ₹{getReportData().reduce((sum, e) => sum + e.amount, 0).toLocaleString('en-IN')}
                    </p>
                    <p className="text-xs text-blue-600 mt-1">{getReportData().length} transactions</p>
                  </div>
                  <div className="space-y-2 max-h-96 overflow-y-auto">
                    {getReportData().length > 0 ? (
                      getReportData().map((expense) => (
                        <div key={expense._id} className="bg-white p-4 rounded-lg shadow-sm">
                          <div className="flex justify-between items-start mb-2">
                            <div>
                              <p className="font-semibold text-gray-900">{expense.description}</p>
                              <p className="text-xs text-gray-500">
                                {new Date(expense.date).toLocaleDateString('en-GB')} • {expense.receivedBy}
                              </p>
                            </div>
                            <p className="font-bold text-gray-900">₹{expense.amount.toLocaleString('en-IN')}</p>
                          </div>
                          <div className="flex gap-2">
                            <span 
                              className="text-xs px-2 py-1 rounded-full"
                              style={{backgroundColor: categories[expense.category].bgColor}}
                            >
                              {categories[expense.category].label}
                            </span>
                            <span 
                              className="text-xs px-2 py-1 rounded-full"
                              style={{backgroundColor: paymentModes[expense.paymentMode].bgColor}}
                            >
                              {paymentModes[expense.paymentMode].label}
                            </span>
                          </div>
                        </div>
                      ))
                    ) : (
                      <div className="text-center py-8 text-gray-500">
                        <p>No expenses found for this period</p>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            <div className="mt-6 flex justify-end">
              <button
                onClick={() => setShowReportModal(false)}
                className="bg-gray-200 hover:bg-gray-300 text-gray-800 px-6 py-2 rounded-lg font-medium transition-colors"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* View Expense Modal */}
      {showViewModal && selectedExpense && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold">Expense Details</h2>
              <button
                onClick={() => {
                  setShowViewModal(false);
                  setSelectedExpense(null);
                }}
                className="text-gray-500 hover:text-gray-700 text-2xl leading-none"
              >
                ✕
              </button>
            </div>

            <div className="space-y-4">
              <div className="bg-gray-50 rounded-lg p-4">
                <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Date</label>
                <p className="text-base font-medium text-gray-900">
                  {new Date(selectedExpense.date).toLocaleDateString('en-GB', { 
                    day: '2-digit', 
                    month: 'long', 
                    year: 'numeric' 
                  })}
                </p>
              </div>

              <div className="bg-gray-50 rounded-lg p-4">
                <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Expense Name</label>
                <p className="text-base font-medium text-gray-900">{selectedExpense.description}</p>
              </div>

              <div className="bg-gray-50 rounded-lg p-4">
                <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Received By</label>
                <p className="text-base font-medium text-gray-900">{selectedExpense.receivedBy}</p>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="bg-gray-50 rounded-lg p-4">
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Category</label>
                  <span 
                    className={`inline-flex px-3 py-1 rounded-full text-xs font-medium ${categories[selectedExpense.category].color}`}
                    style={{backgroundColor: categories[selectedExpense.category].bgColor}}
                  >
                    {categories[selectedExpense.category].label.toUpperCase()}
                  </span>
                </div>

                <div className="bg-gray-50 rounded-lg p-4">
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Payment Mode</label>
                  <span 
                    className={`inline-flex px-3 py-1 rounded-full text-xs font-medium ${paymentModes[selectedExpense.paymentMode].color}`}
                    style={{backgroundColor: paymentModes[selectedExpense.paymentMode].bgColor}}
                  >
                    {paymentModes[selectedExpense.paymentMode].label.toUpperCase()}
                  </span>
                </div>
              </div>

              <div className="bg-green-50 border-2 border-green-200 rounded-lg p-4">
                <label className="block text-xs font-semibold text-green-700 uppercase tracking-wider mb-1">Amount</label>
                <p className="text-3xl font-bold text-green-900">₹{selectedExpense.amount.toLocaleString('en-IN')}</p>
              </div>

              {selectedExpense._id && (
                <div className="bg-gray-50 rounded-lg p-4">
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Transaction ID</label>
                  <p className="text-xs font-mono text-gray-600">{selectedExpense._id}</p>
                </div>
              )}
            </div>

            <div className="mt-6 flex gap-3">
              <button
                onClick={() => {
                  setShowViewModal(false);
                  setSelectedExpense(null);
                }}
                className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-800 py-2 rounded-lg font-medium transition-colors"
              >
                Close
              </button>
              <button
                onClick={() => {
                  if (window.confirm('Are you sure you want to delete this expense?')) {
                    handleDeleteExpense(selectedExpense._id);
                    setShowViewModal(false);
                    setSelectedExpense(null);
                  }
                }}
                className="flex-1 bg-red-500 hover:bg-red-600 text-white py-2 rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
              >
                <Trash2 size={16} />
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Expense;