// Socket instance
let socket = null;

// Initialize WebSocket connection
export const initSocket = () => {
  if (!socket) {
    socket = io('http://localhost:5000', {
      withCredentials: true
    });
    
    socket.on('connect', () => {
      console.log('WebSocket connected');
      socket.emit('joinExpenseRoom');
    });
  }
  return socket;
};

// Get socket instance
export const getSocket = () => socket;

