// Real-time event handlers
export const setupRealTimeListeners = (callbacks) => {
  const socketInstance = getSocket();
  if (!socketInstance) return;
  
  socketInstance.on('expenseAdded', (expense) => {
    if (callbacks.onExpenseAdded) callbacks.onExpenseAdded(expense);
  });
  
  socketInstance.on('expenseUpdated', (expense) => {
    if (callbacks.onExpenseUpdated) callbacks.onExpenseUpdated(expense);
  });
  
  socketInstance.on('expenseDeleted', (data) => {
    if (callbacks.onExpenseDeleted) callbacks.onExpenseDeleted(data);
  });
  
  // Reconnect handling
  socketInstance.on('reconnect', () => {
    console.log('WebSocket reconnected');
    socketInstance.emit('joinExpenseRoom');
  });
};


