// WebSocket for tax management
export const initTaxSocket = () => {
  const socket = initSocket(); // Reuse your existing socket
  
  socket.on('connect', () => {
    console.log('Tax WebSocket connected');
    const token = localStorage.getItem('token');
    if (token) {
      socket.emit('joinTaxRoom', { token });
    }
  });
  
  return socket;
};

