import { Calendar, CreditCard, DollarSign, Download, Eye, FileText, Filter, Mail, Package, Phone, Printer, RefreshCw, Search, User } from 'lucide-react';
import { useEffect, useState } from 'react';

// API Service for Invoice Operations
const invoiceAPI = {
  // Base URL - Update this to match your backend server
  // IMPORTANT: Change this to your actual backend URL
  baseURL: 'http://localhost:5000/api',
  
  // Fetch all invoices from MongoDB
  getAllInvoices: async () => {
    try {
      console.log('🔍 Attempting to fetch from:', `${invoiceAPI.baseURL}/invoices`);
      
      const response = await fetch(`${invoiceAPI.baseURL}/invoices`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      
      console.log('📡 Response status:', response.status);
      console.log('📡 Response OK:', response.ok);
      
      if (!response.ok) {
        const errorText = await response.text();
        console.error('❌ Error response:', errorText);
        throw new Error(`HTTP error! status: ${response.status} - ${errorText}`);
      }
      
      const data = await response.json();
      console.log('✅ Raw data received from backend:', data);
      console.log('✅ Data type:', typeof data);
      console.log('✅ Is Array:', Array.isArray(data));
      console.log('✅ Data length:', data?.length);
      
      return data;
    } catch (error) {
      console.error('❌ Error fetching invoices:', error);
      console.error('❌ Error message:', error.message);
      console.error('❌ Error stack:', error.stack);
      throw error;
    }
  },
  
  // Fetch single invoice by ID
  getInvoiceById: async (id) => {
    try {
      const response = await fetch(`${invoiceAPI.baseURL}/invoices/${id}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const data = await response.json();
      return data;
    } catch (error) {
      console.error('Error fetching invoice:', error);
      throw error;
    }
  }
};

function SalesHistory() {
  const [sales, setSales] = useState([]);
  const [filteredSales, setFilteredSales] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [dateFilter, setDateFilter] = useState('all');
  const [paymentFilter, setPaymentFilter] = useState('all');
  const [selectedBill, setSelectedBill] = useState(null);
  const [showBillModal, setShowBillModal] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    loadSalesData();
  }, []);

  useEffect(() => {
    filterSales();
  }, [searchTerm, dateFilter, paymentFilter, sales]);

  // Load sales data from MongoDB via invoiceAPI
  const loadSalesData = async () => {
    setLoading(true);
    setError(null);
    
    try {
      console.log('🔄 Fetching invoices from backend...');
      console.log('🔄 Backend URL:', invoiceAPI.baseURL);
      
      // Fetch all invoices from your backend
      const invoices = await invoiceAPI.getAllInvoices();
      
      console.log('📡 Invoices received:', invoices);
      console.log('📡 Type of invoices:', typeof invoices);
      console.log('📡 Is Array:', Array.isArray(invoices));
      
      // Handle different response formats
      let invoiceArray = [];
      
      if (Array.isArray(invoices)) {
        invoiceArray = invoices;
      } else if (invoices && typeof invoices === 'object') {
        // Check if it's wrapped in a data property
        if (Array.isArray(invoices.data)) {
          invoiceArray = invoices.data;
          console.log('📦 Found invoices in data property');
        } else if (Array.isArray(invoices.invoices)) {
          invoiceArray = invoices.invoices;
          console.log('📦 Found invoices in invoices property');
        } else {
          console.warn('⚠️ Unexpected response format:', invoices);
        }
      }
      
      console.log('📊 Invoice array length:', invoiceArray.length);
      
      if (invoiceArray.length > 0) {
        console.log('📋 First invoice sample:', JSON.stringify(invoiceArray[0], null, 2));
        
        // Transform invoice data to match sales history format
        const transformedSales = invoiceArray.map((invoice, index) => {
          console.log(`🔄 Transforming invoice ${index + 1}:`, invoice);
          
          return {
            _id: invoice._id || invoice.id || `invoice-${index}`,
            billNumber: invoice.invoiceNumber || invoice.billNumber || invoice.invoice_number || `INV-${index}`,
            date: invoice.createdAt || invoice.date || invoice.created_at || new Date().toISOString(),
            customerName: invoice.customer?.name || invoice.customerName || invoice.customer_name || 'Unknown Customer',
            customerPhone: invoice.customer?.phone || invoice.customerPhone || invoice.phone || 'N/A',
            customerEmail: invoice.customer?.email || invoice.customerEmail || invoice.email || '',
            totalAmount: invoice.totalAmount || invoice.total || invoice.total_amount || 0,
            subtotal: invoice.subtotal || invoice.sub_total || 0,
            gst: invoice.totalGST || invoice.gst || invoice.total_gst || 0,
            paymentMode: invoice.paymentMethod || invoice.paymentMode || invoice.payment_method || 'Cash',
            status: invoice.status || 'Completed',
            items: (invoice.items || invoice.line_items || []).map(item => ({
              name: item.name || item.product_name || 'Item',
              quantity: item.quantity || item.qty || 1,
              price: item.unitPrice || item.price || item.unit_price || 0,
              total: item.totalPrice || item.total || item.total_price || 0,
              gstRate: item.gstRate || item.gst_rate || 0,
              gstAmount: item.gstAmount || item.gst_amount || 0
            })),
            discount: invoice.discount || null,
            gstMode: invoice.gstMode || invoice.gst_mode || 'inclusive',
            taxBreakdown: invoice.taxBreakdown || invoice.tax_breakdown || [],
            whatsappSent: invoice.whatsappSent || invoice.whatsapp_sent || false
          };
        });
        
        // Sort by date (newest first)
        const sortedSales = transformedSales.sort((a, b) => 
          new Date(b.date) - new Date(a.date)
        );
        
        console.log(`✅ Successfully transformed ${sortedSales.length} sales records`);
        console.log('📋 First transformed sale:', sortedSales[0]);
        
        setSales(sortedSales);
        setFilteredSales(sortedSales);
      } else {
        console.log('ℹ️ No invoices found in database');
        console.log('ℹ️ Raw response was:', invoices);
        setSales([]);
        setFilteredSales([]);
      }
      
    } catch (error) {
      console.error('❌ Error loading sales:', error);
      console.error('❌ Error message:', error.message);
      console.error('❌ Error stack:', error.stack);
      setError(`Failed to load sales data: ${error.message}`);
      setSales([]);
      setFilteredSales([]);
    } finally {
      setLoading(false);
    }
  };

  const filterSales = () => {
    let filtered = [...sales];

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(sale =>
        sale.billNumber?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        sale.customerName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        sale.customerPhone?.includes(searchTerm)
      );
    }

    // Date filter
    if (dateFilter !== 'all') {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      
      filtered = filtered.filter(sale => {
        const saleDate = new Date(sale.date);
        saleDate.setHours(0, 0, 0, 0);
        const diffTime = today - saleDate;
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        if (dateFilter === 'today') return diffDays === 0;
        if (dateFilter === 'week') return diffDays <= 7;
        if (dateFilter === 'month') return diffDays <= 30;
        return true;
      });
    }

    // Payment filter
    if (paymentFilter !== 'all') {
      filtered = filtered.filter(sale => 
        sale.paymentMode?.toLowerCase() === paymentFilter.toLowerCase()
      );
    }

    setFilteredSales(filtered);
  };

  const handleViewBill = (sale) => {
    setSelectedBill(sale);
    setShowBillModal(true);
  };

  const handlePrintBill = (sale) => {
    const printWindow = window.open('', '_blank');
    printWindow.document.write(generatePrintHTML(sale));
    printWindow.document.close();
    printWindow.print();
  };

  const generatePrintHTML = (sale) => {
    return `
      <!DOCTYPE html>
      <html>
      <head>
        <title>Invoice - ${sale.billNumber}</title>
        <style>
          body { font-family: Arial, sans-serif; padding: 20px; max-width: 800px; margin: 0 auto; }
          .header { text-align: center; border-bottom: 2px solid #000; padding-bottom: 10px; margin-bottom: 20px; }
          .header h1 { margin: 0; font-size: 32px; }
          .details { margin: 20px 0; }
          .details p { margin: 8px 0; }
          .items table { width: 100%; border-collapse: collapse; margin: 20px 0; }
          .items th, .items td { border: 1px solid #ddd; padding: 10px; text-align: left; }
          .items th { background-color: #f2f2f2; font-weight: bold; }
          .items td { font-size: 14px; }
          .totals { margin-top: 20px; border-top: 2px solid #000; padding-top: 10px; }
          .totals p { text-align: right; font-size: 16px; margin: 8px 0; }
          .totals .final { font-size: 20px; font-weight: bold; }
          .footer { text-align: center; margin-top: 40px; font-style: italic; color: #666; }
          .tax-breakdown { margin: 15px 0; padding: 10px; background: #f9f9f9; border-radius: 5px; }
        </style>
      </head>
      <body>
        <div class="header">
          <h1>INVOICE</h1>
          <p style="font-size: 16px; margin: 5px 0;">Bill Number: ${sale.billNumber}</p>
        </div>
        <div class="details">
          <p><strong>Date:</strong> ${new Date(sale.date).toLocaleDateString('en-IN', { 
            year: 'numeric', 
            month: 'long', 
            day: 'numeric' 
          })}</p>
          <p><strong>Customer:</strong> ${sale.customerName}</p>
          ${sale.customerPhone ? `<p><strong>Phone:</strong> ${sale.customerPhone}</p>` : ''}
          ${sale.customerEmail ? `<p><strong>Email:</strong> ${sale.customerEmail}</p>` : ''}
          <p><strong>Payment Mode:</strong> ${sale.paymentMode?.toUpperCase()}</p>
          ${sale.whatsappSent ? `<p><strong>WhatsApp:</strong> Sent</p>` : ''}
        </div>
        <div class="items">
          <table>
            <thead>
              <tr>
                <th>Item</th>
                <th style="text-align: center;">Quantity</th>
                <th style="text-align: right;">Price</th>
                ${sale.items?.[0]?.gstRate ? '<th style="text-align: right;">GST</th>' : ''}
                <th style="text-align: right;">Total</th>
              </tr>
            </thead>
            <tbody>
              ${sale.items?.map(item => `
                <tr>
                  <td>${item.name}</td>
                  <td style="text-align: center;">${item.quantity}</td>
                  <td style="text-align: right;">₹${parseFloat(item.price).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
                  ${item.gstRate ? `<td style="text-align: right;">${item.gstRate}%</td>` : ''}
                  <td style="text-align: right;">₹${parseFloat(item.total || (item.quantity * item.price)).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
                </tr>
              `).join('') || ''}
            </tbody>
          </table>
        </div>
        
        ${sale.taxBreakdown?.length > 0 ? `
          <div class="tax-breakdown">
            <p style="font-weight: bold; margin-bottom: 8px;">Tax Breakdown:</p>
            ${sale.taxBreakdown.map(tax => `
              <p style="display: flex; justify-content: space-between; margin: 4px 0;">
                <span>${tax.taxName}:</span>
                <span>₹${parseFloat(tax.amount).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
              </p>
            `).join('')}
          </div>
        ` : ''}
        
        <div class="totals">
          ${sale.subtotal ? `<p><strong>Subtotal:</strong> ₹${parseFloat(sale.subtotal).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>` : ''}
          <p><strong>Total GST:</strong> ₹${parseFloat(sale.gst || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
          ${sale.discount?.discountAmount > 0 ? `
            <p><strong>Discount (${sale.discount.code}):</strong> -₹${parseFloat(sale.discount.discountAmount).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
          ` : ''}
          <p class="final"><strong>Total Amount:</strong> ₹${parseFloat(sale.totalAmount).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
          ${sale.gstMode ? `<p style="font-size: 12px; color: #666;">GST Mode: ${sale.gstMode.toUpperCase()}</p>` : ''}
        </div>
        <div class="footer">
          <p>Thank you for your business!</p>
        </div>
      </body>
      </html>
    `;
  };

  const exportToCSV = () => {
    const headers = ['Bill Number', 'Date', 'Customer Name', 'Phone', 'Total Amount', 'GST', 'Payment Mode', 'Status'];
    const csvData = filteredSales.map(sale => [
      sale.billNumber,
      new Date(sale.date).toLocaleDateString('en-IN'),
      sale.customerName,
      sale.customerPhone || 'N/A',
      parseFloat(sale.totalAmount).toFixed(2),
      parseFloat(sale.gst || 0).toFixed(2),
      sale.paymentMode?.toUpperCase() || 'N/A',
      sale.status || 'Completed'
    ]);
    
    const csv = [headers, ...csvData].map(row => row.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `sales_history_${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  const totalSales = filteredSales.reduce((sum, sale) => sum + parseFloat(sale.totalAmount || 0), 0);
  const totalGST = filteredSales.reduce((sum, sale) => sum + parseFloat(sale.gst || 0), 0);

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h1 className="text-3xl font-bold text-gray-800">Sales History</h1>
              <p className="text-gray-600 mt-1">View all invoices and sales records</p>
            </div>
            <div className="flex gap-2">
              <button
                onClick={loadSalesData}
                disabled={loading}
                className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <RefreshCw size={20} className={loading ? 'animate-spin' : ''} />
                Refresh
              </button>
              <button
                onClick={exportToCSV}
                disabled={filteredSales.length === 0}
                className="flex items-center gap-2 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Download size={20} />
                Export CSV
              </button>
            </div>
          </div>

          {/* Loading State */}
          {loading && (
            <div className="text-center py-8">
              <RefreshCw className="animate-spin mx-auto mb-2 text-blue-600" size={32} />
              <p className="text-gray-600">Loading sales data from MongoDB...</p>
            </div>
          )}

          {/* Error State */}
          {error && !loading && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
              <p className="text-red-800 font-medium">⚠️ Error loading sales data</p>
              <p className="text-red-600 text-sm mt-1">{error}</p>
              <p className="text-red-600 text-sm mt-1">Make sure your backend server is running at http://localhost:5000</p>
            </div>
          )}

          {/* Summary Cards */}
          {!loading && !error && (
            <>
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                <div className="bg-blue-50 p-4 rounded-lg">
                  <div className="flex items-center gap-3">
                    <FileText className="text-blue-600" size={24} />
                    <div>
                      <p className="text-gray-600 text-sm">Total Invoices</p>
                      <p className="text-2xl font-bold text-gray-800">{filteredSales.length}</p>
                    </div>
                  </div>
                </div>
                <div className="bg-green-50 p-4 rounded-lg">
                  <div className="flex items-center gap-3">
                    <DollarSign className="text-green-600" size={24} />
                    <div>
                      <p className="text-gray-600 text-sm">Total Revenue</p>
                      <p className="text-2xl font-bold text-gray-800">₹{totalSales.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</p>
                    </div>
                  </div>
                </div>
                <div className="bg-purple-50 p-4 rounded-lg">
                  <div className="flex items-center gap-3">
                    <CreditCard className="text-purple-600" size={24} />
                    <div>
                      <p className="text-gray-600 text-sm">Average Sale</p>
                      <p className="text-2xl font-bold text-gray-800">
                        ₹{filteredSales.length > 0 ? (totalSales / filteredSales.length).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '0.00'}
                      </p>
                    </div>
                  </div>
                </div>
                <div className="bg-orange-50 p-4 rounded-lg">
                  <div className="flex items-center gap-3">
                    <FileText className="text-orange-600" size={24} />
                    <div>
                      <p className="text-gray-600 text-sm">Total GST</p>
                      <p className="text-2xl font-bold text-gray-800">₹{totalGST.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Filters */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="relative">
                  <Search className="absolute left-3 top-3 text-gray-400" size={20} />
                  <input
                    type="text"
                    placeholder="Search by bill number, customer, or phone..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                <div className="relative">
                  <Calendar className="absolute left-3 top-3 text-gray-400" size={20} />
                  <select
                    value={dateFilter}
                    onChange={(e) => setDateFilter(e.target.value)}
                    className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent appearance-none"
                  >
                    <option value="all">All Dates</option>
                    <option value="today">Today</option>
                    <option value="week">Last 7 Days</option>
                    <option value="month">Last 30 Days</option>
                  </select>
                </div>

                <div className="relative">
                  <Filter className="absolute left-3 top-3 text-gray-400" size={20} />
                  <select
                    value={paymentFilter}
                    onChange={(e) => setPaymentFilter(e.target.value)}
                    className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent appearance-none"
                  >
                    <option value="all">All Payment Modes</option>
                    <option value="cash">Cash</option>
                    <option value="card">Card</option>
                    <option value="upi">UPI</option>
                    <option value="bank_transfer">Bank Transfer</option>
                  </select>
                </div>
              </div>
            </>
          )}
        </div>

        {/* Sales Table */}
        {!loading && !error && (
          <div className="bg-white rounded-lg shadow-md overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Invoice Number
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Date
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Customer
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Items
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Total Amount
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Payment
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Status
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {filteredSales.length === 0 ? (
                    <tr>
                      <td colSpan="8" className="px-6 py-8 text-center text-gray-500">
                        <Package size={48} className="mx-auto mb-2 text-gray-300" />
                        <p className="font-medium">No sales records found</p>
                        <p className="text-sm mt-1">{sales.length === 0 ? 'Create your first invoice from the Billing page!' : 'Try adjusting your filters.'}</p>
                      </td>
                    </tr>
                  ) : (
                    filteredSales.map((sale) => (
                      <tr key={sale._id} className="hover:bg-gray-50 transition">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="flex items-center">
                            <FileText className="text-blue-600 mr-2" size={18} />
                            <span className="text-sm font-medium text-gray-900">{sale.billNumber}</span>
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <span className="text-sm text-gray-900">
                            {new Date(sale.date).toLocaleDateString('en-IN', { 
                              year: 'numeric', 
                              month: 'short', 
                              day: 'numeric' 
                            })}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center">
                            <User className="text-gray-400 mr-2" size={18} />
                            <div>
                              <div className="text-sm font-medium text-gray-900">{sale.customerName}</div>
                              {sale.customerPhone && (
                                <div className="text-xs text-gray-500 flex items-center gap-1">
                                  <Phone size={12} />
                                  {sale.customerPhone}
                                </div>
                              )}
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <span className="text-sm text-gray-700">
                            {sale.items?.length || 0} items
                          </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div>
                            <span className="text-sm font-semibold text-green-600">
                              ₹{parseFloat(sale.totalAmount).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </span>
                            {sale.gst > 0 && (
                              <div className="text-xs text-gray-500">
                                GST: ₹{parseFloat(sale.gst).toFixed(2)}
                              </div>
                            )}
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <span className={`px-3 py-1 inline-flex text-xs leading-5 font-semibold rounded-full ${
                            sale.paymentMode?.toLowerCase() === 'cash' ? 'bg-green-100 text-green-800' :
                            sale.paymentMode?.toLowerCase() === 'card' ? 'bg-blue-100 text-blue-800' :
                            sale.paymentMode?.toLowerCase() === 'upi' ? 'bg-purple-100 text-purple-800' :
                            'bg-orange-100 text-orange-800'
                          }`}>
                            {sale.paymentMode?.toUpperCase() || 'N/A'}
                          </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <span className="px-3 py-1 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">
                            {sale.status || 'Completed'}
                          </span>
                          {sale.whatsappSent && (
                            <div className="text-xs text-green-600 mt-1"></div>
                          )}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                          <div className="flex gap-2">
                            <button
                              onClick={() => handleViewBill(sale)}
                              className="text-blue-600 hover:text-blue-900 flex items-center gap-1 px-3 py-1 rounded hover:bg-blue-50 transition"
                            >
                              <Eye size={16} />
                              View
                            </button>
                            <button
                              onClick={() => handlePrintBill(sale)}
                              className="text-green-600 hover:text-green-900 flex items-center gap-1 px-3 py-1 rounded hover:bg-green-50 transition"
                            >
                              <Printer size={16} />
                              Print
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* Bill View Modal */}
      {showBillModal && selectedBill && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg shadow-xl max-w-3xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6">
              <div className="flex justify-between items-center mb-6 border-b pb-4">
                <h2 className="text-2xl font-bold text-gray-800">Invoice Details</h2>
                <button
                  onClick={() => setShowBillModal(false)}
                  className="text-gray-500 hover:text-gray-700 text-2xl font-bold w-8 h-8 flex items-center justify-center rounded hover:bg-gray-100"
                >
                  ×
                </button>
              </div>

              <div className="space-y-6">
                {/* Header Info */}
                <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-lg">
                  <div>
                    <p className="text-sm text-gray-600">Invoice Number</p>
                    <p className="text-lg font-bold text-gray-800">{selectedBill.billNumber}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">Date</p>
                    <p className="text-lg font-semibold text-gray-800">
                      {new Date(selectedBill.date).toLocaleDateString('en-IN', { 
                        year: 'numeric', 
                        month: 'long', 
                        day: 'numeric' 
                      })}
                    </p>
                  </div>
                </div>

                {/* Customer Info */}
                <div className="border border-gray-200 rounded-lg p-4">
                  <h3 className="font-bold text-gray-800 mb-3 flex items-center gap-2">
                    <User size={18} className="text-blue-600" />
                    Customer Information
                  </h3>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <p className="text-sm text-gray-600">Name</p>
                      <p className="font-semibold text-gray-800">{selectedBill.customerName}</p>
                    </div>
                    {selectedBill.customerPhone && (
                      <div>
                        <p className="text-sm text-gray-600">Phone</p>
                        <p className="font-semibold text-gray-800 flex items-center gap-1">
                          <Phone size={14} />
                          {selectedBill.customerPhone}
                        </p>
                      </div>
                    )}
                    {selectedBill.customerEmail && (
                      <div>
                        <p className="text-sm text-gray-600">Email</p>
                        <p className="font-semibold text-gray-800 flex items-center gap-1">
                          <Mail size={14} />
                          {selectedBill.customerEmail}
                        </p>
                      </div>
                    )}
                    <div>
                      <p className="text-sm text-gray-600">Payment Method</p>
                      <p className="font-semibold text-gray-800">{selectedBill.paymentMode?.toUpperCase()}</p>
                    </div>
                  </div>
                </div>

                {/* Items Table */}
                <div>
                  <h3 className="text-lg font-semibold text-gray-800 mb-3 flex items-center gap-2">
                    <Package size={18} className="text-green-600" />
                    Items
                  </h3>
                  <div className="overflow-x-auto border border-gray-200 rounded-lg">
                    <table className="w-full">
                      <thead className="bg-gray-50">
                        <tr>
                          <th className="px-4 py-3 text-left text-sm font-medium text-gray-600">Item</th>
                          <th className="px-4 py-3 text-center text-sm font-medium text-gray-600">Qty</th>
                          <th className="px-4 py-3 text-right text-sm font-medium text-gray-600">Price</th>
                          {selectedBill.items?.[0]?.gstRate && (
                            <th className="px-4 py-3 text-right text-sm font-medium text-gray-600">GST</th>
                          )}
                          <th className="px-4 py-3 text-right text-sm font-medium text-gray-600">Total</th>
                        </tr>
                      </thead>
                      <tbody>
                        {selectedBill.items?.map((item, idx) => (
                          <tr key={idx} className="border-t border-gray-200 hover:bg-gray-50">
                            <td className="px-4 py-3 text-sm text-gray-800">{item.name}</td>
                            <td className="px-4 py-3 text-sm text-center text-gray-800">{item.quantity}</td>
                            <td className="px-4 py-3 text-sm text-right text-gray-800">
                              ₹{parseFloat(item.price).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </td>
                            {item.gstRate && (
                              <td className="px-4 py-3 text-sm text-right text-gray-600">
                                {item.gstRate}%
                              </td>
                            )}
                            <td className="px-4 py-3 text-sm font-semibold text-right text-gray-800">
                              ₹{parseFloat(item.total || (item.quantity * item.price)).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>

                {/* Tax Breakdown */}
                {selectedBill.taxBreakdown?.length > 0 && (
                  <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                    <h4 className="font-bold text-gray-800 mb-3">Tax Breakdown</h4>
                    <div className="space-y-2">
                      {selectedBill.taxBreakdown.map((tax, idx) => (
                        <div key={idx} className="flex justify-between text-sm">
                          <span className="text-gray-700">{tax.taxName}:</span>
                          <span className="font-semibold text-gray-800">
                            ₹{parseFloat(tax.amount).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Totals */}
                <div className="border-t pt-4 space-y-3">
                  {selectedBill.subtotal && (
                    <div className="flex justify-between text-gray-700">
                      <span className="font-medium">Subtotal:</span>
                      <span className="font-semibold">
                        ₹{parseFloat(selectedBill.subtotal).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                      </span>
                    </div>
                  )}
                  
                  <div className="flex justify-between text-gray-700">
                    <span className="font-medium">Total GST:</span>
                    <span className="font-semibold">
                      ₹{parseFloat(selectedBill.gst || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </span>
                  </div>

                  {selectedBill.discount?.discountAmount > 0 && (
                    <div className="flex justify-between text-green-700">
                      <span className="font-medium">Discount ({selectedBill.discount.code}):</span>
                      <span className="font-semibold">
                        -₹{parseFloat(selectedBill.discount.discountAmount).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                      </span>
                    </div>
                  )}
                  
                  <div className="flex justify-between text-xl border-t pt-3">
                    <span className="font-bold text-gray-800">Total Amount:</span>
                    <span className="font-bold text-green-600">
                      ₹{parseFloat(selectedBill.totalAmount).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </span>
                  </div>

                  {selectedBill.gstMode && (
                    <div className="text-xs text-gray-500 text-right">
                      GST Mode: {selectedBill.gstMode.toUpperCase()}
                    </div>
                  )}
                </div>

                {/* Status Badges */}
                <div className="flex gap-3 flex-wrap">
                  <div className="flex items-center gap-2 px-3 py-2 bg-green-50 border border-green-200 rounded-lg">
                    <span className="text-sm font-medium text-green-800">
                      Status: {selectedBill.status || 'Completed'}
                    </span>
                  </div>
                  {selectedBill.whatsappSent && (
                    <div className="flex items-center gap-2 px-3 py-2 bg-blue-50 border border-blue-200 rounded-lg">
                      <span className="text-sm font-medium text-blue-800">WhatsApp Sent</span>
                    </div>
                  )}
                </div>

                {/* Action Buttons */}
                <div className="flex gap-3 pt-4">
                  <button
                    onClick={() => handlePrintBill(selectedBill)}
                    className="flex-1 bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition flex items-center justify-center gap-2 font-semibold"
                  >
                    <Printer size={20} />
                    Print Invoice
                  </button>
                  <button
                    onClick={() => setShowBillModal(false)}
                    className="flex-1 bg-gray-200 text-gray-800 px-6 py-3 rounded-lg hover:bg-gray-300 transition font-semibold"
                  >
                    Close
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default SalesHistory;