import {
  BarChart3,
  Bell,
  Boxes,
  ChevronRight,
  Eye,
  FileText,
  History,
  Receipt,
  ShoppingCart,
  Users,
  X,
  Tag,
  Ticket,
  LayoutDashboard,
  IndianRupee,
  Coins,
  PackageSearch, // Added for Products
  Layers // Optional alternative for Products
} from 'lucide-react';
import { useState } from 'react';

const Sidebar = ({ currentPage, setCurrentPage, isMobileOpen, setIsMobileOpen, currentUser }) => {
  const [expandedMenus, setExpandedMenus] = useState({});

  // Brand Colors
  const brandGreen = '#A8E4A0'; 
  const deepGreen = '#065F46';  
  const softGreen = '#F0FDF4';  

  const menuSections = [
    {
      label: 'Main',
      items: [
        { id: 'dashboard', name: 'Dashboard', icon: LayoutDashboard },
        { id: 'notifications', name: 'Notifications', icon: Bell },
      ]
    },
    {
      label: 'Sales & Billing',
      items: [
        { id: 'billing', name: 'Invoices', icon: Receipt },
        { id: 'sales-history', name: 'Sales History', icon: History },
        { id: 'expenses', name: 'Expenses', icon: IndianRupee },
        { id: 'ledger', name: 'Wallet', icon: Coins }
      ]
    },
    {
      label: 'Inventory',
      items: [
        { id: 'products', name: 'Products', icon: PackageSearch }, // NEW ITEM
        { id: 'stock-management', name: 'Stock Control', icon: Boxes },
        { id: 'orders', name: 'Orders', icon: ShoppingCart },
        { id: 'discounts', name: 'Deals & Tags', icon: Tag },
        { id: 'coupons', name: 'Coupons', icon: Ticket }
      ]
    },
    {
      label: 'Management',
      items: [
        { id: 'customers', name: 'Customers', icon: Users },
        { id: 'reports', name: 'General Reports', icon: FileText },
        { id: 'gst', name: 'GST & Tax', icon: FileText },
      ]
    }
  ];

  const handleMenuClick = (item) => {
    setCurrentPage(item.id);
    if (isMobileOpen) setIsMobileOpen(false);
  };

  return (
    <>
      {/* Mobile Overlay */}
      <div
        className={`fixed inset-0 bg-slate-900/60 backdrop-blur-md z-40 lg:hidden transition-opacity duration-300 ${
          isMobileOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
        }`}
        onClick={() => setIsMobileOpen(false)}
      />

      {/* Sidebar */}
      <aside
        className={`fixed lg:static inset-y-0 left-0 z-50 w-64 bg-white border-r border-gray-100 flex flex-col transform transition-all duration-300 ease-in-out shadow-xl lg:shadow-none ${
          isMobileOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
        }`}
      >
        {/* 1. Logo Section */}
        <div className="h-20 flex items-center justify-between px-6">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl flex items-center justify-center shadow-lg shadow-emerald-100 shrink-0 rotate-3 group-hover:rotate-0 transition-transform" style={{ backgroundColor: brandGreen }}>
              <BarChart3 size={22} style={{ color: deepGreen }} />
            </div>
            <span className="text-xl font-black tracking-tighter" style={{ color: deepGreen }}>
              BILLING<span className="text-emerald-500">.</span>
            </span>
          </div>
          <button onClick={() => setIsMobileOpen(false)} className="lg:hidden p-2 hover:bg-gray-100 rounded-full">
            <X size={20} className="text-gray-400" />
          </button>
        </div>

        {/* 2. User Profile Section */}
        <div className="px-4 mb-4">
          <div className="flex items-center gap-3 p-3 rounded-2xl border border-emerald-100/50 bg-gradient-to-br from-white to-emerald-50/30 shadow-sm">
            <div className="w-11 h-11 rounded-xl flex items-center justify-center text-white text-base font-bold shadow-md shrink-0 transition-transform hover:scale-105" style={{ backgroundColor: deepGreen }}>
              {currentUser?.name?.charAt(0) || 'A'}
            </div>
            <div className="overflow-hidden">
              <p className="text-sm font-bold text-slate-800 truncate">
                {currentUser?.name || 'Admin User'}
              </p>
              <span className="inline-block px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-emerald-100 text-emerald-700">
                {currentUser?.role || 'Administrator'}
              </span>
            </div>
          </div>
        </div>

        {/* 3. Navigation Menu */}
        <nav className="flex-1 px-3 space-y-7 overflow-y-auto pb-6 scrollbar-hide">
          {menuSections.map((section) => (
            <div key={section.label}>
              <h3 className="px-4 mb-3 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400/80">
                {section.label}
              </h3>
              <div className="space-y-1">
                {section.items.map((item) => {
                  const isActive = currentPage === item.id;
                  return (
                    <button
                      key={item.id}
                      onClick={() => handleMenuClick(item)}
                      className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all duration-200 group relative ${
                        isActive 
                          ? 'shadow-md shadow-emerald-100/50 scale-[1.02]' 
                          : 'hover:bg-emerald-50/60'
                      }`}
                      style={{
                        backgroundColor: isActive ? brandGreen : 'transparent',
                      }}
                    >
                      {isActive && (
                        <div className="absolute left-0 w-1 h-5 bg-emerald-600 rounded-r-full" />
                      )}
                      <item.icon 
                        size={19} 
                        className={`transition-all ${isActive ? 'scale-110' : 'text-slate-400 group-hover:text-emerald-600 group-hover:translate-x-0.5'}`}
                        style={{ color: isActive ? deepGreen : undefined }}
                      />
                      <span 
                        className={`text-sm font-semibold transition-colors ${isActive ? '' : 'text-slate-600 group-hover:text-emerald-900'}`}
                        style={{ color: isActive ? deepGreen : undefined }}
                      >
                        {item.name}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </nav>
      
      </aside>
    </>
  );
};

export default Sidebar;