import { AlertTriangle, CheckCircle, Download, Edit, Eye, Loader, Minus, Package, Plus, RefreshCw, Search, X, XCircle } from 'lucide-react';
import { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import io from 'socket.io-client';

const API_BASE_URL = 'http://localhost:5000/api';
const SOCKET_URL = 'http://localhost:5000';
let socket;

const StockManagement = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [showStockUpdateModal, setShowStockUpdateModal] = useState(false);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [stockUpdateAmount, setStockUpdateAmount] = useState('');
  const [updateType, setUpdateType] = useState('add');
  const [showAlert, setShowAlert] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');
  const [alertType, setAlertType] = useState('success');
  const [stockData, setStockData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    total: 0,
    lowStock: 0,
    outOfStock: 0,
    normal: 0
  });
  const [socketConnected, setSocketConnected] = useState(false);

  // Initialize Socket Connection
  useEffect(() => {
    console.log('🔄 Stock Management: Initializing socket connection...');
    
    socket = io(SOCKET_URL, {
      transports: ['websocket', 'polling'],
      reconnection: true,
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
    });
    
    socket.on('connect', () => {
      console.log('✅ Stock Management: Socket connected, ID:', socket.id);
      setSocketConnected(true);
    });
    
    socket.on('connect_error', (error) => {
      console.error('❌ Stock Management: Socket connection error:', error);
      setSocketConnected(false);
    });
    
    socket.on('disconnect', () => {
      console.log('❌ Stock Management: Socket disconnected');
      setSocketConnected(false);
    });
    
    // Listen for notification confirmations
    socket.on('notification_created', (data) => {
      console.log('📦 Stock notification confirmed:', data);
    });
    
    // Join notification room
    socket.emit('joinNotificationRoom');
    
    return () => {
      if (socket) {
        socket.off('connect');
        socket.off('connect_error');
        socket.off('disconnect');
        socket.off('notification_created');
      }
    };
  }, []);

  const showNotification = useCallback((message, type = 'success') => {
    setAlertMessage(message);
    setAlertType(type);
    setShowAlert(true);
    setTimeout(() => setShowAlert(false), 3000);
  }, []);

  const calculateStockStatus = useCallback((currentStock, minLevel) => {
    if (currentStock === 0) return 'out';
    if (currentStock <= minLevel) return 'low';
    return 'normal';
  }, []);

  const calculateStatsFromProducts = useCallback((products) => {
    const calculatedStats = {
      total: products.length,
      normal: 0,
      lowStock: 0,
      outOfStock: 0
    };
    
    products.forEach(item => {
      const currentStock = item.currentStock !== undefined ? item.currentStock : 
                         (item.stock !== undefined ? item.stock : 0);
      const minLevel = item.minStockLevel !== undefined ? item.minStockLevel :
                      (item.minStock !== undefined ? item.minStock : 10);
      
      const status = calculateStockStatus(currentStock, minLevel);
      
      if (status === 'out') calculatedStats.outOfStock++;
      else if (status === 'low') calculatedStats.lowStock++;
      else calculatedStats.normal++;
    });
    
    return calculatedStats;
  }, [calculateStockStatus]);

  const fetchProducts = useCallback(async (search = '', status = 'all') => {
    try {
      setLoading(true);
      
      const response = await axios.get(`${API_BASE_URL}/products`);
      
      if (response.data.success && Array.isArray(response.data.data)) {
        let processedData = response.data.data.map(item => {
          const currentStock = item.stock !== undefined ? item.stock : 
                             (item.currentStock !== undefined ? item.currentStock : 0);
          const minLevel = item.minStock !== undefined ? item.minStock :
                          (item.minStockLevel !== undefined ? item.minStockLevel : 10);
          
          const calculatedStatus = calculateStockStatus(currentStock, minLevel);
          
          return {
            _id: item._id || item.id,
            productId: item.productId || item.productCode || item._id,
            name: item.name || item.productName || 'Unknown Product',
            category: item.category || 'Uncategorized',
            currentStock,
            minStockLevel: minLevel,
            status: item.status || calculatedStatus,
            price: item.price !== undefined ? item.price : 0,
            maxStockLevel: item.maxStock || item.maxStockLevel || minLevel * 5,
            lastRestocked: item.lastRestocked || item.updatedAt || item.createdAt || new Date()
          };
        });
        
        // Calculate stats from ALL products before filtering
        const allProductsStats = calculateStatsFromProducts(processedData);
        setStats(allProductsStats);
        
        // Apply search filter
        if (search && search.trim() !== '') {
          const searchLower = search.toLowerCase().trim();
          processedData = processedData.filter(item => 
            (item.name && item.name.toLowerCase().includes(searchLower)) ||
            (item.productId && item.productId.toLowerCase().includes(searchLower)) ||
            (item.category && item.category.toLowerCase().includes(searchLower)) ||
            (item.sku && item.sku.toLowerCase().includes(searchLower))
          );
        }
        
        // Apply status filter
        if (status && status !== 'all') {
          processedData = processedData.filter(item => item.status === status);
        }
        
        setStockData(processedData);
      } else {
        showNotification('Invalid data format received', 'error');
        setStockData([]);
        setStats({ total: 0, lowStock: 0, outOfStock: 0, normal: 0 });
      }
    } catch (error) {
      showNotification(`Error: ${error.message}`, 'error');
      setStockData([]);
      setStats({ total: 0, lowStock: 0, outOfStock: 0, normal: 0 });
    } finally {
      setLoading(false);
    }
  }, [showNotification, calculateStatsFromProducts, calculateStockStatus]);

  // Auto-check for low stock items on load
  useEffect(() => {
    const checkInitialLowStock = async () => {
      if (!loading && stockData.length > 0 && socketConnected) {
        stockData.forEach(product => {
          const currentStock = product.currentStock || 0;
          const minLevel = product.minStockLevel || 10;
          
          if (currentStock <= minLevel) {
            const notificationType = currentStock === 0 ? 'Out of Stock' : 'Low Stock';
            
            // Emit socket notification for existing low stock
            if (socket && socket.connected) {
              const notification = {
                _id: `initial_${product._id}_${Date.now()}`,
                type: notificationType,
                title: `${notificationType} Alert`,
                message: `${product.name} ${currentStock === 0 ? 'is out of stock' : `has low stock (${currentStock} units)`}`,
                productName: product.name,
                productId: product._id,
                currentStock: currentStock,
                minStock: minLevel,
                timestamp: new Date().toISOString(),
                isRead: false,
                color: currentStock === 0 ? 'red' : 'orange',
                icon: 'Package',
                priority: currentStock === 0 ? 'high' : 'medium'
              };
              
              socket.emit('new_notification', notification);
              console.log('📦 Initial low stock notification sent:', product.name);
            }
          }
        });
      }
    };
    
    checkInitialLowStock();
  }, [loading, stockData, socketConnected]);

  // Debounce search term
  const useDebounce = (value, delay) => {
    const [debouncedValue, setDebouncedValue] = useState(value);

    useEffect(() => {
      const handler = setTimeout(() => {
        setDebouncedValue(value);
      }, delay);

      return () => {
        clearTimeout(handler);
      };
    }, [value, delay]);

    return debouncedValue;
  };

  const debouncedSearchTerm = useDebounce(searchTerm, 300);

  useEffect(() => {
    let isMounted = true;
    let intervalId;

    const loadData = async () => {
      if (!isMounted) return;
      await fetchProducts(debouncedSearchTerm, filterStatus);
    };

    loadData();

    // Set up refresh interval
    intervalId = setInterval(loadData, 60000);

    return () => {
      isMounted = false;
      clearInterval(intervalId);
    };
  }, [debouncedSearchTerm, filterStatus, fetchProducts]);

  const getStatusBadge = useCallback((status) => {
    switch (status) {
      case 'low':
        return {
          bg: '#FEF3C7',
          text: '#92400E',
          label: 'Low Stock',
          icon: AlertTriangle
        };
      case 'out':
        return {
          bg: '#FEE2E2',
          text: '#991B1B',
          label: 'Out of Stock',
          icon: XCircle
        };
      case 'normal':
        return {
          bg: '#D1FAE5',
          text: '#065F46',
          label: 'In Stock',
          icon: CheckCircle
        };
      default:
        return {
          bg: '#E5E7EB',
          text: '#374151',
          label: 'Unknown',
          icon: Package
        };
    }
  }, []);

  const getProgressColor = useCallback((status) => {
    switch (status) {
      case 'out':
        return '#EF4444';
      case 'low':
        return '#F59E0B';
      case 'normal':
        return '#10B981';
      default:
        return '#9CA3AF';
    }
  }, []);

  const calculateProgressPercentage = useCallback((current, min) => {
    if (min === 0) return current > 0 ? 100 : 0;
    const percentage = (current / (min * 2)) * 100;
    return Math.min(Math.max(percentage, 0), 100);
  }, []);

  const handleStockUpdate = useCallback(async () => {
  if (!selectedProduct || !stockUpdateAmount) {
    showNotification('Please enter a valid quantity', 'error');
    return;
  }

  const amount = parseInt(stockUpdateAmount);
  if (isNaN(amount) || amount <= 0) {
    showNotification('Please enter a valid positive number', 'error');
    return;
  }

  try {
    const newStock = updateType === 'add' 
      ? selectedProduct.currentStock + amount 
      : selectedProduct.currentStock - amount;

    if (newStock < 0) {
      showNotification('Cannot remove more stock than available', 'error');
      return;
    }

    // Update stock in database
    const response = await axios.put(
      `${API_BASE_URL}/products/${selectedProduct._id}`,
      {
        stock: newStock,
        currentStock: newStock,
        lastRestocked: new Date().toISOString()
      }
    );

    if (response.data.success || response.status === 200) {
      showNotification(
        `Successfully ${updateType === 'add' ? 'added' : 'removed'} ${amount} units ${updateType === 'add' ? 'to' : 'from'} ${selectedProduct.name}`,
        'success'
      );
      
      // Check if we need to create a notification
      const minLevel = selectedProduct.minStockLevel ?? selectedProduct.minStock ?? 10;
      const maxLevel = selectedProduct.maxStockLevel ?? selectedProduct.maxStock ?? minLevel * 5;
      
      let shouldNotify = false;
      let notificationType = '';
      let priority = 'medium';
      let color = 'orange';
      
      if (newStock === 0) {
        shouldNotify = true;
        notificationType = 'Out of Stock';
        priority = 'high';
        color = 'red';
      } else if (newStock <= minLevel) {
        shouldNotify = true;
        notificationType = 'Low Stock';
        priority = newStock <= (minLevel * 0.3) ? 'high' : 'medium';
        color = newStock <= (minLevel * 0.3) ? 'red' : 'orange';
      }
      
      if (shouldNotify) {
        try {
          // Create notification via API
          const notifResponse = await axios.post(
            `${API_BASE_URL}/notifications/check-stock`,
            {
              productId: selectedProduct._id,
              productName: selectedProduct.name,
              currentStock: newStock,
              minStock: minLevel,
              maxStock: maxLevel
            }
          );
          
          console.log('📦 Notification created:', notifResponse.data);
          
          // Also emit socket event for real-time notification
          if (socket && socket.connected) {
            const socketData = {
              productId: selectedProduct._id,
              productName: selectedProduct.name,
              currentStock: newStock,
              minStock: minLevel,
              timestamp: new Date().toISOString()
            };
            
            socket.emit('stock_updated', socketData);
            console.log('📦 Socket event emitted for stock update');
          }
          
        } catch (notifError) {
          console.error('❌ Notification API failed:', notifError);
          
          // Fallback: Use socket directly
          if (socket && socket.connected) {
            const socketData = {
              productId: selectedProduct._id,
              productName: selectedProduct.name,
              currentStock: newStock,
              minStock: minLevel,
              timestamp: new Date().toISOString()
            };
            
            socket.emit('stock_updated', socketData);
            console.log('📦 Fallback socket event emitted');
          }
        }
      }

      // Refresh data
      await fetchProducts(debouncedSearchTerm, filterStatus);
      
      setShowStockUpdateModal(false);
      setSelectedProduct(null);
      setStockUpdateAmount('');
    } else {
      showNotification(response.data.message || 'Failed to update stock', 'error');
    }
  } catch (error) {
    console.error('Error in stock update:', error);
    showNotification('Error connecting to server', 'error');
  }
}, [selectedProduct, stockUpdateAmount, updateType, showNotification, fetchProducts, debouncedSearchTerm, filterStatus]);

  const handleRefresh = useCallback(async () => {
    setSearchTerm('');
    setFilterStatus('all');
    await fetchProducts('', 'all');
    showNotification('Stock data refreshed successfully', 'success');
  }, [fetchProducts, showNotification]);

  const handleExport = useCallback(() => {
    const csvContent = [
      ['Product ID', 'Product Name', 'Category', 'Current Stock', 'Min Level', 'Status', 'Price', 'Last Restocked'],
      ...stockData.map(item => [
        item.productId || item._id,
        item.name,
        item.category,
        item.currentStock,
        item.minStockLevel,
        item.status,
        item.price,
        new Date(item.lastRestocked).toLocaleDateString()
      ])
    ].map(row => row.join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `stock-report-${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);

    showNotification('Stock report exported successfully', 'success');
  }, [stockData, showNotification]);

  const handleViewDetails = useCallback((product) => {
    setSelectedProduct(product);
    setShowDetailsModal(true);
  }, []);

  // Test real-time notification function
  const testRealTimeNotification = async () => {
    try {
      if (socket && socket.connected) {
        const testNotification = {
          _id: `test_${Date.now()}`,
          type: 'Low Stock',
          title: 'Test Real-time Alert',
          message: 'This is a real-time test notification from Stock Management',
          productName: 'Test Product',
          productId: 'test123',
          currentStock: 3,
          minStock: 10,
          timestamp: new Date().toISOString(),
          isRead: false,
          color: 'red',
          icon: 'Package',
          priority: 'high'
        };
        
        socket.emit('test_notification', testNotification);
        showNotification('Test real-time notification sent!', 'success');
        console.log('Test notification emitted:', testNotification);
      } else {
        showNotification('Socket not connected. Please refresh.', 'error');
      }
    } catch (error) {
      console.error('Test failed:', error);
      showNotification('Test failed: ' + error.message, 'error');
    }
  };

  const filteredStockData = useMemo(() => {
    return stockData;
  }, [stockData]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-6">
      {showAlert && (
        <div
          className="fixed top-4 right-4 z-50 px-6 py-4 rounded-lg shadow-lg flex items-center gap-3 animate-slide-in"
          style={{
            backgroundColor: alertType === 'success' ? '#D1FAE5' : '#FEE2E2',
            color: alertType === 'success' ? '#065F46' : '#991B1B',
            animation: 'slideIn 0.3s ease-out'
          }}
        >
          {alertType === 'success' ? <CheckCircle size={20} /> : <XCircle size={20} />}
          <span className="font-medium">{alertMessage}</span>
        </div>
      )}

      {/* Socket Status Indicator */}
      {/* Socket Status Indicator */}

      {/* Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 hover:shadow-lg transition-all duration-300 transform hover:-translate-y-1">
          <div className="flex items-center justify-between mb-2">
            <div>
              <p className="text-gray-500 text-sm font-medium mb-2">Total Products</p>
              <p className="text-4xl font-bold text-blue-600">{stats.total}</p>
            </div>
            <div className="p-4 rounded-2xl bg-blue-50">
              <Package className="text-blue-600" size={32} strokeWidth={2.5} />
            </div>
          </div>
        </div>
        
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 hover:shadow-lg transition-all duration-300 transform hover:-translate-y-1">
          <div className="flex items-center justify-between mb-2">
            <div>
              <p className="text-gray-500 text-sm font-medium mb-2">In Stock</p>
              <p className="text-4xl font-bold text-green-600">{stats.normal}</p>
            </div>
            <div className="p-4 rounded-2xl bg-green-50">
              <CheckCircle className="text-green-600" size={32} strokeWidth={2.5} />
            </div>
          </div>
        </div>
        
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 hover:shadow-lg transition-all duration-300 transform hover:-translate-y-1">
          <div className="flex items-center justify-between mb-2">
            <div>
              <p className="text-gray-500 text-sm font-medium mb-2">Low Stock</p>
              <p className="text-4xl font-bold text-yellow-600">{stats.lowStock}</p>
            </div>
            <div className="p-4 rounded-2xl bg-yellow-50">
              <AlertTriangle className="text-yellow-600" size={32} strokeWidth={2.5} />
            </div>
          </div>
        </div>
        
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 hover:shadow-lg transition-all duration-300 transform hover:-translate-y-1">
          <div className="flex items-center justify-between mb-2">
            <div>
              <p className="text-gray-500 text-sm font-medium mb-2">Out of Stock</p>
              <p className="text-4xl font-bold text-red-600">{stats.outOfStock}</p>
            </div>
            <div className="p-4 rounded-2xl bg-red-50">
              <XCircle className="text-red-600" size={32} strokeWidth={2.5} />
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 mb-6">
        <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
          <div className="relative flex-1 w-full">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="Search products by name or code..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-400"
            />
          </div>

          <div className="flex gap-3 w-full md:w-auto">
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-400"
            >
              <option value="all">All Status</option>
              <option value="normal">In Stock</option>
              <option value="low">Low Stock</option>
              <option value="out">Out of Stock</option>
            </select>

            <button
              onClick={handleExport}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition flex items-center gap-2"
            >
              <Download size={18} />
              Export
            </button>

            <button
              onClick={handleRefresh}
              className="px-4 py-2 text-white rounded-lg transition flex items-center gap-2"
              style={{ backgroundColor: '#A8E4A0' }}
            >
              <RefreshCw size={18} />
              Refresh
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
        {loading ? (
          <div className="flex items-center justify-center py-20">
            <Loader className="animate-spin text-gray-400" size={40} />
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase">PRODUCT ID</th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase">PRODUCT NAME</th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase">CURRENT STOCK</th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase">MIN LEVEL</th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase">STATUS</th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase">PRICE</th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase">LAST RESTOCKED</th>
                  <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase">ACTIONS</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {filteredStockData.map((item) => {
                  const currentStock = item.currentStock ?? 0;
                  const minLevel = item.minStockLevel ?? 10;
                  const itemStatus = item.status || calculateStockStatus(currentStock, minLevel);
                  const statusConfig = getStatusBadge(itemStatus);
                  const StatusIcon = statusConfig.icon;
                  const progressPercentage = calculateProgressPercentage(currentStock, minLevel);
                  const progressColor = getProgressColor(itemStatus);

                  return (
                    <tr key={item._id} className="hover:bg-gray-50 transition">
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className="font-mono text-sm font-medium text-gray-900">
                          {item.productId}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <div>
                          <p className="font-medium text-gray-900">{item.name}</p>
                          <p className="text-sm text-gray-500">{item.category}</p>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="space-y-1">
                          <div className="flex items-center gap-2">
                            <span className="text-lg font-semibold text-gray-900">
                              {currentStock} units
                            </span>
                          </div>
                          <div className="w-24">
                            <div className="h-2 bg-gray-200 rounded-full overflow-hidden">
                              <div
                                className="h-full rounded-full transition-all duration-300"
                                style={{
                                  width: `${progressPercentage}%`,
                                  backgroundColor: progressColor
                                }}
                              />
                            </div>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className="text-gray-600">{minLevel}</span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span
                          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-medium"
                          style={{
                            backgroundColor: statusConfig.bg,
                            color: statusConfig.text
                          }}
                        >
                          <StatusIcon size={14} />
                          {statusConfig.label}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className="font-medium text-gray-900">
                          ₹{item.price.toLocaleString()}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="flex flex-col">
                          <span className="text-sm text-gray-900">
                            {item.lastRestocked ? new Date(item.lastRestocked).toLocaleDateString() : 'Never'}
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="flex gap-2">
                          <button
                            onClick={() => {
                              setSelectedProduct(item);
                              setShowStockUpdateModal(true);
                              setUpdateType('add');
                            }}
                            className="p-2 rounded-lg transition"
                            style={{ backgroundColor: '#A8E4A020', color: '#A8E4A0' }}
                          >
                            <Edit size={18} />
                          </button>
                          <button
                            onClick={() => handleViewDetails(item)}
                            className="p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition"
                          >
                            <Eye size={18} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {!loading && filteredStockData.length === 0 && (
          <div className="text-center py-20">
            <Package className="mx-auto text-gray-300 mb-4" size={64} />
            <h3 className="text-lg font-medium text-gray-900 mb-2">No products found</h3>
            <p className="text-gray-500">Try adjusting your search or filter</p>
          </div>
        )}
      </div>

      {showStockUpdateModal && selectedProduct && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-gray-800">Update Stock</h2>
              <button
                onClick={() => {
                  setShowStockUpdateModal(false);
                  setSelectedProduct(null);
                  setStockUpdateAmount('');
                }}
                className="text-gray-400 hover:text-gray-600"
              >
                <X size={24} />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Product</label>
                <div className="p-3 bg-gray-50 rounded-lg">
                  <p className="font-medium text-gray-900">{selectedProduct.name}</p>
                  <p className="text-sm text-gray-500">ID: {selectedProduct.productId || selectedProduct._id}</p>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Current Stock</label>
                <div className="p-3 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-gray-900">{selectedProduct.currentStock} units</p>
                  <p className="text-sm text-gray-500 mt-1">Min Level: {selectedProduct.minStockLevel}</p>
                  <div className="mt-3">
                    <div className="h-3 bg-gray-200 rounded-full overflow-hidden">
                      <div
                        className="h-full rounded-full transition-all duration-300"
                        style={{
                          width: `${calculateProgressPercentage(selectedProduct.currentStock, selectedProduct.minStockLevel)}%`,
                          backgroundColor: getProgressColor(selectedProduct.status)
                        }}
                      />
                    </div>
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Update Type</label>
                <div className="flex gap-2">
                  <button
                    onClick={() => setUpdateType('add')}
                    className={`flex-1 py-2 px-4 rounded-lg font-medium transition ${
                      updateType === 'add' ? 'text-white' : 'bg-gray-100 text-gray-700'
                    }`}
                    style={updateType === 'add' ? { backgroundColor: '#A8E4A0' } : {}}
                  >
                    <Plus className="inline mr-2" size={18} />
                    Add Stock
                  </button>
                  <button
                    onClick={() => setUpdateType('remove')}
                    className={`flex-1 py-2 px-4 rounded-lg font-medium transition ${
                      updateType === 'remove' ? 'bg-red-500 text-white' : 'bg-gray-100 text-gray-700'
                    }`}
                  >
                    <Minus className="inline mr-2" size={18} />
                    Remove Stock
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Quantity</label>
                <input
                  type="number"
                  min="1"
                  value={stockUpdateAmount}
                  onChange={(e) => setStockUpdateAmount(e.target.value)}
                  placeholder="Enter quantity"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-400"
                />
              </div>
            </div>

            <div className="flex gap-3 mt-6">
              <button
                onClick={() => {
                  setShowStockUpdateModal(false);
                  setSelectedProduct(null);
                  setStockUpdateAmount('');
                }}
                className="flex-1 px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition"
              >
                Cancel
              </button>
              <button
                onClick={handleStockUpdate}
                className="flex-1 px-4 py-2 text-white rounded-lg transition"
                style={{ backgroundColor: '#A8E4A0' }}
              >
                Update Stock
              </button>
            </div>
          </div>
        </div>
      )}

      {showDetailsModal && selectedProduct && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full p-6 max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-gray-800">Product Details</h2>
              <button
                onClick={() => {
                  setShowDetailsModal(false);
                  setSelectedProduct(null);
                }}
                className="text-gray-400 hover:text-gray-600"
              >
                <X size={24} />
              </button>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Product Name</label>
                <p className="text-gray-900 font-medium">{selectedProduct.name || 'N/A'}</p>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Product ID</label>
                <p className="text-gray-900 font-mono text-sm">{selectedProduct.productId || 'N/A'}</p>
              </div>
          
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Category</label>
                <p className="text-gray-900">{selectedProduct.category || 'N/A'}</p>
              </div>
              <div className="col-span-2">
                <label className="block text-sm font-medium text-gray-600 mb-1">Current Stock</label>
                <div className="flex items-center gap-4">
                  <p className="text-gray-900 font-bold text-lg">
                    {selectedProduct.currentStock !== undefined ? selectedProduct.currentStock : 0} units
                  </p>
                  <div className="flex-1">
                    <div className="h-3 bg-gray-200 rounded-full overflow-hidden">
                      <div
                        className="h-full rounded-full transition-all duration-300"
                        style={{
                          width: `${calculateProgressPercentage(selectedProduct.currentStock, selectedProduct.minStockLevel)}%`,
                          backgroundColor: getProgressColor(selectedProduct.status)
                        }}
                      />
                    </div>
                  </div>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Min Level</label>
                <p className="text-gray-900">
                  {selectedProduct.minStockLevel !== undefined ? selectedProduct.minStockLevel : 0} units
                </p>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Max Stock Level</label>
                <p className="text-gray-900">
                  {selectedProduct.maxStockLevel !== undefined ? selectedProduct.maxStockLevel : 0} units
                </p>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Price</label>
                <p className="text-gray-900 font-semibold">
                  ₹{selectedProduct.price ? selectedProduct.price.toLocaleString() : '0'}
                </p>
              </div>
            
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Last Restocked</label>
                <p className="text-gray-900">
                  {selectedProduct.lastRestocked ? new Date(selectedProduct.lastRestocked).toLocaleDateString() : 'Never'}
                </p>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Status</label>
                <span
                  className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-medium"
                  style={{
                    backgroundColor: getStatusBadge(selectedProduct.status).bg,
                    color: getStatusBadge(selectedProduct.status).text
                  }}
                >
                  {getStatusBadge(selectedProduct.status).label}
                </span>
              </div>
            </div>

            <div className="flex gap-3 mt-6">
              <button
                onClick={() => {
                  setShowDetailsModal(false);
                  setShowStockUpdateModal(true);
                }}
                className="flex-1 px-4 py-2 text-white rounded-lg transition"
                style={{ backgroundColor: '#A8E4A0' }}
              >
                Update Stock
              </button>
              <button
                onClick={() => {
                  setShowDetailsModal(false);
                  setSelectedProduct(null);
                }}
                className="flex-1 px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {stats.lowStock > 0 && (
        <div className="fixed bottom-6 right-6 bg-yellow-50 border-l-4 border-yellow-400 p-4 rounded-lg shadow-lg max-w-md animate-bounce-slow">
          <div className="flex items-center gap-3">
            <AlertTriangle className="text-yellow-600" size={24} />
            <div>
              <p className="font-semibold text-yellow-800">Low Stock Alert!</p>
              <p className="text-sm text-yellow-700">
                {stats.lowStock} product{stats.lowStock > 1 ? 's are' : ' is'} running low on stock
              </p>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes slideIn {
          from {
            transform: translateX(100%);
            opacity: 0;
          }
          to {
            transform: translateX(0);
            opacity: 1;
          }
        }
        
        @keyframes bounce-slow {
          0%, 100% {
            transform: translateY(0);
          }
          50% {
            transform: translateY(-5px);
          }
        }
        
        .animate-bounce-slow {
          animation: bounce-slow 2s infinite;
        }
      `}</style>
    </div>
  );
};

export default StockManagement;