import { useState } from 'react';

const LoginPage = ({ onLoginSuccess }) => {
  const [selectedUserType, setSelectedUserType] = useState('admin');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [showForgotPassword, setShowForgotPassword] = useState(false);
  const [resetEmail, setResetEmail] = useState('');
  const [resetSuccess, setResetSuccess] = useState(false);

  const handleUserTypeChange = (type) => {
    setSelectedUserType(type);
    setError('');
  };
const handleLogin = async () => {
  setError('');

  if (!username.trim() || !password) {
    setError('Please enter both username and password');
    return;
  }

  try {
    const res = await fetch('http://localhost:5000/api/auth/login', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        username,
        password,
        role: selectedUserType
      })
    });

    const data = await res.json();

    if (!res.ok) {
      throw new Error(data.message || 'Login failed');
    }

    // Save for session / offline usage
    localStorage.setItem('token', data.token);
    localStorage.setItem('user', JSON.stringify(data.user));

    onLoginSuccess({
      name: data.user.name,
      role: data.user.role
    });

  } catch (err) {
    setError(err.message);
  }
};


  const handleKeyPress = (e) => {
    if (e.key === 'Enter') handleLogin();
  };

  const handleForgotPassword = () => {
    setError('');
    setResetSuccess(false);
    if (!resetEmail.trim()) {
      setError('Please enter your email address');
      return;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(resetEmail)) {
      setError('Please enter a valid email address');
      return;
    }
    setResetSuccess(true);
    setTimeout(() => {
      setShowForgotPassword(false);
      setResetEmail('');
      setResetSuccess(false);
    }, 3000);
  };

  return (
    <div
      className="min-h-screen flex items-center justify-center p-5 relative overflow-hidden"
      style={{ 
        background: 'linear-gradient(135deg, #A8E4A0 0%, #7ec474 100%)',
      }}
    >
      {/* Decorative Glass Bubbles for background depth */}
      <div className="absolute w-64 h-64 rounded-full -top-20 -left-20 opacity-30" style={{ background: '#ffffff' }}></div>
      <div className="absolute w-96 h-96 rounded-full -bottom-20 -right-20 opacity-20" style={{ background: '#2D8A3E' }}></div>

      <div className="w-full max-w-md z-10">
        <div
          className="rounded-3xl overflow-hidden border border-white/30"
          style={{ 
            background: 'rgba(255, 255, 255, 0.25)',
            backdropFilter: 'blur(15px)',
            WebkitBackdropFilter: 'blur(15px)',
            boxShadow: '0 8px 32px 0 rgba(31, 38, 135, 0.15)',
          }}
        >
          {/* Header */}
          <div className="text-center p-10 bg-white/10 border-b border-white/20">
            <div className="w-20 h-20 bg-white/40 backdrop-blur-md rounded-2xl flex items-center justify-center mx-auto mb-4 border border-white/50">
              <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#1F2937" strokeWidth="2">
                <rect x="3" y="11" width="18" height="11" rx="2" />
                <path d="M7 11V7a5 5 0 0 1 10 0v4" />
              </svg>
            </div>
            <h1 className="text-3xl font-black text-gray-900 tracking-tight">Billing System</h1>
            <p className="text-gray-700 font-medium text-sm mt-1">Secure Business Access</p>
          </div>

          {/* Body */}
          <div className="p-8">
            {!showForgotPassword ? (
              <>
                {error && (
                  <div className="bg-red-500/20 backdrop-blur-md border border-red-500/50 text-red-900 px-4 py-3 rounded-xl mb-4 text-sm font-medium">
                    {error}
                  </div>
                )}

                {/* User Type - Role-based Login */}
                <div className="mb-6">
                  <label className="block text-sm font-bold text-gray-800 mb-3">Login as</label>
                  <div className="grid grid-cols-2 gap-4">
                    {['admin', 'staff'].map((type) => (
                      <button
                        key={type}
                        type="button"
                        onClick={() => handleUserTypeChange(type)}
                        className="py-3 rounded-xl border font-bold transition-all duration-300"
                        style={{
                          background: selectedUserType === type ? 'rgba(255, 255, 255, 0.5)' : 'rgba(255, 255, 255, 0.1)',
                          borderColor: selectedUserType === type ? 'rgba(255, 255, 255, 0.8)' : 'rgba(255, 255, 255, 0.2)',
                          color: '#1F2937',
                          boxShadow: selectedUserType === type ? '0 4px 12px rgba(0,0,0,0.05)' : 'none'
                        }}
                      >
                        {type.charAt(0).toUpperCase() + type.slice(1)}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Inputs */}
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-bold text-gray-800 mb-2">Username</label>
                    <input
                      type="text"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      onKeyPress={handleKeyPress}
                      className="w-full px-4 py-3 rounded-xl bg-white/30 border border-white/50 focus:bg-white/50 focus:outline-none transition-all placeholder-gray-600 text-gray-900"
                      placeholder="Enter username"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-bold text-gray-800 mb-2">Password</label>
                    <input
                      type="password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      onKeyPress={handleKeyPress}
                      className="w-full px-4 py-3 rounded-xl bg-white/30 border border-white/50 focus:bg-white/50 focus:outline-none transition-all placeholder-gray-600 text-gray-900"
                      placeholder="Enter password"
                    />
                  </div>
                </div>

                <div className="text-right mt-3 mb-6">
                  <button
                    type="button"
                    onClick={() => { setShowForgotPassword(true); setError(''); }}
                    className="text-sm font-bold text-gray-800 hover:text-white transition-colors"
                  >
                    Forgot Password?
                  </button>
                </div>

                <button
                  type="button"
                  onClick={handleLogin}
                  className="w-full py-4 rounded-xl font-black text-lg transition-all active:scale-95"
                  style={{
                    background: '#1F2937',
                    color: '#A8E4A0',
                    boxShadow: '0 10px 20px rgba(0,0,0,0.1)'
                  }}
                >
                  Login to Dashboard
                </button>
              </>
            ) : (
              <>
                <h2 className="text-xl font-black text-gray-900 mb-2">Reset Password</h2>
                <p className="text-gray-700 text-sm mb-6">Enter your email for a reset link.</p>

                {error && <div className="bg-red-500/20 border border-red-500/50 text-red-900 px-4 py-3 rounded-xl mb-4 text-sm font-medium">{error}</div>}
                {resetSuccess && <div className="bg-green-500/20 border border-green-500/50 text-green-900 px-4 py-3 rounded-xl mb-4 text-sm font-medium">Link sent!</div>}

                <input
                  type="email"
                  value={resetEmail}
                  onChange={(e) => setResetEmail(e.target.value)}
                  className="w-full px-4 py-3 rounded-xl bg-white/30 border border-white/50 focus:bg-white/50 focus:outline-none transition-all mb-6 text-gray-900"
                  placeholder="Enter your email"
                />

                <button
                  type="button"
                  onClick={handleForgotPassword}
                  className="w-full py-4 rounded-xl font-black text-lg transition-all mb-4"
                  style={{ background: '#1F2937', color: '#A8E4A0' }}
                >
                  Send Reset Link
                </button>

                <button
                  type="button"
                  onClick={() => { setShowForgotPassword(false); setError(''); }}
                  className="w-full py-3 rounded-xl font-bold text-sm border border-white/50 text-gray-800 hover:bg-white/20 transition-all"
                >
                  Back to Login
                </button>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;