import {
    AlertCircle,
    Bell,
    Calendar,
    CheckCircle,
    Clock,
    CreditCard,
    DollarSign,
    FileText,
    Filter,
    Package,
    Trash2,
    TrendingDown,
    X
} from 'lucide-react';
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import io from 'socket.io-client';

const API_BASE_URL = 'http://localhost:5000/api';
const SOCKET_URL = 'http://localhost:5000';
let socket;

const NotificationsPage = () => {
  const [filterType, setFilterType] = useState('All');
  const [showModal, setShowModal] = useState(false);
  const [selectedNotification, setSelectedNotification] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    unreadCount: 0,
    lowStockCount: 0,
    gstAlertCount: 0,
    paymentAlertCount: 0
  });
  const [socketConnected, setSocketConnected] = useState(false);

  // Fetch notifications
  const fetchNotifications = async () => {
    try {
      setLoading(true);
      const response = await axios.get(`${API_BASE_URL}/notifications`);
      setNotifications(response.data);
      
      // Calculate statistics
      const unread = response.data.filter(n => !n.isRead).length;
      const lowStock = response.data.filter(n => 
        (n.type === 'Low Stock' || n.type === 'Out of Stock') && !n.isRead
      ).length;
      const gstAlert = response.data.filter(n => n.type === 'GST Alert' && !n.isRead).length;
      const paymentAlert = response.data.filter(n => n.type === 'Payment Alert' && !n.isRead).length;
      
      setStats({
        unreadCount: unread,
        lowStockCount: lowStock,
        gstAlertCount: gstAlert,
        paymentAlertCount: paymentAlert
      });
    } catch (error) {
      console.error('Error fetching notifications:', error);
    } finally {
      setLoading(false);
    }
  };

  // Show toast notification
  const showNotificationToast = (notification) => {
    // Remove any existing toast with same ID
    const existingToast = document.getElementById(`toast_${notification._id}`);
    if (existingToast) {
      existingToast.remove();
    }

    const toast = document.createElement('div');
    toast.id = `toast_${notification._id}`;
    toast.className = 'fixed top-4 right-4 z-50 bg-white rounded-lg shadow-lg p-4 border-l-4 animate-slide-in cursor-pointer';
    toast.style.borderLeftColor = notification.color === 'red' ? '#EF4444' : 
                                  notification.color === 'orange' ? '#F59E0B' : 
                                  notification.color === 'green' ? '#10B981' : '#3B82F6';
    toast.style.minWidth = '300px';
    toast.style.zIndex = '9999';
    
    const IconComponent = getIconComponent(notification.icon);
    
    toast.innerHTML = `
      <div class="flex items-start gap-3">
        <div class="p-2 rounded-lg" style="background-color: ${notification.color === 'red' ? '#FEE2E2' : 
                                            notification.color === 'orange' ? '#FEF3C7' : 
                                            notification.color === 'green' ? '#D1FAE5' : '#DBEAFE'}">
          <div style="color: ${notification.color === 'red' ? '#EF4444' : 
                          notification.color === 'orange' ? '#F59E0B' : 
                          notification.color === 'green' ? '#10B981' : '#3B82F6'}">
            ${IconComponent ? `<${IconComponent.name} size="20" />` : '<Bell size="20" />'}
          </div>
        </div>
        <div>
          <p class="font-bold text-gray-800 text-sm">${notification.title}</p>
          <p class="text-xs text-gray-600">${notification.message}</p>
          <p class="text-xs text-gray-500 mt-1">Just now</p>
        </div>
        <button class="ml-auto text-gray-400 hover:text-gray-600" onclick="this.closest('[id^=toast_]').remove()">
          <X size="16" />
        </button>
      </div>
    `;
    
    // Click to view notification
    toast.onclick = () => {
      handleNotificationClick(notification);
      toast.remove();
    };
    
    document.body.appendChild(toast);
    
    // Remove toast after 5 seconds
    setTimeout(() => {
      if (toast.parentNode) {
        toast.style.animation = 'slideOut 0.3s ease-out forwards';
        setTimeout(() => {
          if (toast.parentNode) {
            toast.parentNode.removeChild(toast);
          }
        }, 300);
      }
    }, 5000);
  };

  // Set up socket connection
  useEffect(() => {
    console.log('🔄 Initializing socket connection...');
    socket = io(SOCKET_URL, {
      transports: ['websocket', 'polling'],
      reconnection: true,
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
      timeout: 10000
    });
    
    // Fetch initial notifications
    fetchNotifications();
    
    // Socket event handlers
    socket.on('connect', () => {
      console.log('✅ Socket.io Connected! ID:', socket.id);
      setSocketConnected(true);
      
      // Join notification room
      socket.emit('joinNotificationRoom');
      console.log('Joined notification room');
    });

    socket.on('connect_error', (error) => {
      console.error('❌ Socket connection error:', error);
      setSocketConnected(false);
    });

    socket.on('disconnect', (reason) => {
      console.log('❌ Socket disconnected:', reason);
      setSocketConnected(false);
    });

    // Listen for new notifications from Stock Management
    // Listen for new notifications from Stock Management
socket.on('new_notification', (notification) => {
  console.log('📢 REAL-TIME: New notification received:', notification);
  
  // Check if this is a valid notification from database
  if (notification._id && typeof notification._id === 'object') {
    // This is a valid MongoDB document with ObjectId
    
    // Show toast
    showNotificationToast(notification);
    
    // Add to notifications list at the top
    setNotifications(prev => [notification, ...prev]);
    
    // Update stats
    const isStockNotification = notification.type === 'Low Stock' || notification.type === 'Out of Stock';
    setStats(prev => ({
      unreadCount: prev.unreadCount + 1,
      lowStockCount: isStockNotification ? prev.lowStockCount + 1 : prev.lowStockCount,
      gstAlertCount: notification.type === 'GST Alert' ? prev.gstAlertCount + 1 : prev.gstAlertCount,
      paymentAlertCount: notification.type === 'Payment Alert' ? prev.paymentAlertCount + 1 : prev.paymentAlertCount
    }));
  } else {
    console.log('⚠️ Skipping invalid notification format:', notification);
  }
});
    // Test socket connection
    setTimeout(() => {
      if (socket && socket.connected) {
        console.log('✅ Socket is active and connected');
      } else {
        console.log('❌ Socket not connected, attempting reconnect...');
      }
    }, 1000);

    // Cleanup on unmount
    return () => {
      console.log('🔌 Cleaning up socket connection...');
      if (socket) {
        socket.off('connect');
        socket.off('connect_error');
        socket.off('disconnect');
        socket.off('new_notification');
        socket.disconnect();
      }
    };
  }, []);

  // Test socket connection function
  const testSocketConnection = async () => {
    try {
      // Test backend endpoint
      const response = await axios.get(`${API_BASE_URL}/test`);
      console.log('Backend test:', response.data);
      
      // Test socket
      if (socket && socket.connected) {
        console.log('Socket connected:', socket.id);
        
        // Create test notification
        const testNotification = {
          _id: `test_${Date.now()}`,
          type: 'Low Stock',
          title: 'Test Notification',
          message: 'This is a test notification from the Notifications page',
          productName: 'Test Product',
          currentStock: 5,
          minStock: 10,
          timestamp: new Date().toISOString(),
          isRead: false,
          color: 'orange',
          icon: 'Package',
          priority: 'medium'
        };
        
        socket.emit('test_notification', testNotification);
        showNotificationToast(testNotification);
        
        // Add to local state
        setNotifications(prev => [testNotification, ...prev]);
        setStats(prev => ({
          ...prev,
          unreadCount: prev.unreadCount + 1,
          lowStockCount: prev.lowStockCount + 1
        }));
        
      } else {
        console.log('Socket not connected, reconnecting...');
        socket.connect();
      }
    } catch (error) {
      console.error('Test failed:', error);
    }
  };

  // Filter notifications
  const filteredNotifications = notifications.filter(notification => {
    if (filterType === 'All') return true;
    if (filterType === 'Stock Alerts') {
      return notification.type === 'Low Stock' || notification.type === 'Out of Stock';
    }
    return notification.type === filterType;
  });

  const markAsRead = async (id) => {
    try {
      // Update in backend if it's a real notification (not socket-only)
      if (!id.startsWith('socket_') && !id.startsWith('test_') && !id.startsWith('fallback_')) {
        await axios.put(`${API_BASE_URL}/notifications/${id}/read`);
      }
      
      // Update local state
      setNotifications(notifications.map(n => 
        n._id === id ? { ...n, isRead: true } : n
      ));
      
      // Update stats
      const notification = notifications.find(n => n._id === id);
      if (notification && !notification.isRead) {
        const isStockNotification = notification.type.includes('Stock');
        setStats(prev => ({
          ...prev,
          unreadCount: prev.unreadCount - 1,
          lowStockCount: isStockNotification ? prev.lowStockCount - 1 : prev.lowStockCount,
          gstAlertCount: notification.type === 'GST Alert' ? prev.gstAlertCount - 1 : prev.gstAlertCount,
          paymentAlertCount: notification.type === 'Payment Alert' ? prev.paymentAlertCount - 1 : prev.paymentAlertCount
        }));
      }
    } catch (error) {
      console.error('Error marking as read:', error);
    }
  };

  const markAllAsRead = async () => {
    try {
      // Mark all as read in backend
      await axios.put(`${API_BASE_URL}/notifications/mark-all-read`);
      
      // Update local state
      setNotifications(notifications.map(n => ({ ...n, isRead: true })));
      setStats({
        unreadCount: 0,
        lowStockCount: 0,
        gstAlertCount: 0,
        paymentAlertCount: 0
      });
    } catch (error) {
      console.error('Error marking all as read:', error);
    }
  };

  const deleteNotification = async (id) => {
    try {
      // Delete from backend if it's a real notification
      if (!id.startsWith('socket_') && !id.startsWith('test_') && !id.startsWith('fallback_')) {
        await axios.delete(`${API_BASE_URL}/notifications/${id}`);
      }
      
      const notification = notifications.find(n => n._id === id);
      setNotifications(notifications.filter(n => n._id !== id));
      
      // Update stats if notification was unread
      if (notification && !notification.isRead) {
        const isStockNotification = notification.type.includes('Stock');
        setStats(prev => ({
          ...prev,
          unreadCount: prev.unreadCount - 1,
          lowStockCount: isStockNotification ? prev.lowStockCount - 1 : prev.lowStockCount,
          gstAlertCount: notification.type === 'GST Alert' ? prev.gstAlertCount - 1 : prev.gstAlertCount,
          paymentAlertCount: notification.type === 'Payment Alert' ? prev.paymentAlertCount - 1 : prev.paymentAlertCount
        }));
      }
    } catch (error) {
      console.error('Error deleting notification:', error);
    }
  };

  const clearAllRead = async () => {
    try {
      // Clear read from backend
      await axios.delete(`${API_BASE_URL}/notifications/clear-read`);
      
      // Update local state
      setNotifications(notifications.filter(n => !n.isRead));
    } catch (error) {
      console.error('Error clearing read notifications:', error);
    }
  };

  const handleNotificationClick = (notification) => {
    setSelectedNotification(notification);
    setShowModal(true);
    if (!notification.isRead) {
      markAsRead(notification._id);
    }
  };

  const getPriorityColor = (priority) => {
    switch(priority) {
      case 'high': return 'border-red-500 bg-red-50';
      case 'medium': return 'border-yellow-500 bg-yellow-50';
      case 'low': return 'border-green-500 bg-green-50';
      default: return 'border-gray-500 bg-gray-50';
    }
  };

  const getIconColor = (color) => {
    const colors = {
      red: 'text-red-600 bg-red-100',
      orange: 'text-orange-600 bg-orange-100',
      purple: 'text-purple-600 bg-purple-100',
      green: 'text-green-600 bg-green-100',
      blue: 'text-blue-600 bg-blue-100'
    };
    return colors[color] || 'text-gray-600 bg-gray-100';
  };

  const formatDate = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('en-IN', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch (error) {
      return 'Invalid date';
    }
  };

  const formatTimeAgo = (dateString) => {
    try {
      const date = new Date(dateString);
      const now = new Date();
      const diffMs = now - date;
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMs / 3600000);
      const diffDays = Math.floor(diffMs / 86400000);
      
      if (diffMins < 1) {
        return 'Just now';
      } else if (diffMins < 60) {
        return `${diffMins} min ago`;
      } else if (diffHours < 24) {
        return `${diffHours} hours ago`;
      } else if (diffDays < 7) {
        return `${diffDays} days ago`;
      } else {
        return formatDate(dateString);
      }
    } catch (error) {
      return 'Recently';
    }
  };

  // Function to get icon component by name
  const getIconComponent = (iconName) => {
    const icons = {
      Package: Package,
      FileText: FileText,
      CreditCard: CreditCard,
      AlertCircle: AlertCircle,
      Bell: Bell,
      TrendingDown: TrendingDown
    };
    return icons[iconName] || Bell;
  };

  if (loading) {
    return (
      <div className="p-6 bg-gray-50 min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading notifications...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
      <style>{`
        @keyframes slideIn {
          from {
            transform: translateX(100%);
            opacity: 0;
          }
          to {
            transform: translateX(0);
            opacity: 1;
          }
        }
        @keyframes slideOut {
          from {
            transform: translateX(0);
            opacity: 1;
          }
          to {
            transform: translateX(100%);
            opacity: 0;
          }
        }
      `}</style>
      
   

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-800 mb-2">Notifications</h1>
          <p className="text-gray-600">Real-time alerts and reminders</p>
          {stats.unreadCount > 0 && (
            <div className="inline-flex items-center gap-2 mt-1">
              <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
              <span className="text-sm text-gray-600">Live updates active</span>
            </div>
          )}
        </div>
        <div className="flex gap-3">
          <button
            onClick={markAllAsRead}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition shadow-md"
          >
            <CheckCircle size={18} />
            Mark All Read
          </button>
          <button
            onClick={clearAllRead}
            className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition shadow-md"
          >
            <Trash2 size={18} />
            Clear Read
          </button>
        </div>
      </div>

      {/* Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-6">
        <div className="bg-white p-6 rounded-xl shadow-md border-l-4" style={{ borderLeftColor: '#A8E4A0' }}>
          <div className="flex items-center justify-between mb-2">
            <div className="p-3 rounded-lg" style={{ backgroundColor: '#A8E4A015' }}>
              <Bell style={{ color: '#A8E4A0' }} size={24} />
            </div>
            <span className="text-2xl font-bold" style={{ color: '#A8E4A0' }}>{stats.unreadCount}</span>
          </div>
          <h3 className="text-sm font-semibold text-gray-600">Unread Notifications</h3>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-md border-l-4 border-red-500">
          <div className="flex items-center justify-between mb-2">
            <div className="p-3 bg-red-100 rounded-lg">
              <Package className="text-red-600" size={24} />
            </div>
            <span className="text-2xl font-bold text-red-600">{stats.lowStockCount}</span>
          </div>
          <h3 className="text-sm font-semibold text-gray-600">Stock Alerts</h3>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-md border-l-4 border-purple-500">
          <div className="flex items-center justify-between mb-2">
            <div className="p-3 bg-purple-100 rounded-lg">
              <FileText className="text-purple-600" size={24} />
            </div>
            <span className="text-2xl font-bold text-purple-600">{stats.gstAlertCount}</span>
          </div>
          <h3 className="text-sm font-semibold text-gray-600">GST Due Alerts</h3>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-md border-l-4 border-green-500">
          <div className="flex items-center justify-between mb-2">
            <div className="p-3 bg-green-100 rounded-lg">
              <CreditCard className="text-green-600" size={24} />
            </div>
            <span className="text-2xl font-bold text-green-600">{stats.paymentAlertCount}</span>
          </div>
          <h3 className="text-sm font-semibold text-gray-600">Payment Alerts</h3>
        </div>
      </div>

      {/* Filter Tabs */}
      <div className="bg-white p-4 rounded-xl shadow-md border border-gray-100 mb-6">
        <div className="flex items-center gap-2 flex-wrap">
          <Filter size={18} className="text-gray-600" />
          <button
            onClick={() => setFilterType('All')}
            className={`px-4 py-2 rounded-lg font-medium transition ${
              filterType === 'All'
                ? 'text-white shadow-md'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
            style={filterType === 'All' ? { backgroundColor: '#A8E4A0' } : {}}
          >
            All ({notifications.length})
          </button>
          <button
            onClick={() => setFilterType('Stock Alerts')}
            className={`px-4 py-2 rounded-lg font-medium transition ${
              filterType === 'Stock Alerts'
                ? 'bg-red-500 text-white shadow-md'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            Stock Alerts ({notifications.filter(n => n.type === 'Low Stock' || n.type === 'Out of Stock').length})
          </button>
          <button
            onClick={() => setFilterType('GST Alert')}
            className={`px-4 py-2 rounded-lg font-medium transition ${
              filterType === 'GST Alert'
                ? 'bg-purple-500 text-white shadow-md'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            GST Alerts ({notifications.filter(n => n.type === 'GST Alert').length})
          </button>
          <button
            onClick={() => setFilterType('Payment Alert')}
            className={`px-4 py-2 rounded-lg font-medium transition ${
              filterType === 'Payment Alert'
                ? 'bg-green-500 text-white shadow-md'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            Payment Alerts ({notifications.filter(n => n.type === 'Payment Alert').length})
          </button>
        </div>
      </div>

      {/* Notifications List */}
      <div className="space-y-4">
        {filteredNotifications.length === 0 ? (
          <div className="bg-white rounded-xl shadow-md p-12 text-center">
            <Bell size={64} className="mx-auto mb-4 text-gray-300" />
            <h3 className="text-xl font-bold text-gray-400 mb-2">No Notifications</h3>
            <p className="text-gray-500">You're all caught up!</p>
          </div>
        ) : (
          filteredNotifications.map((notification) => {
            const IconComponent = getIconComponent(notification.icon);
            const isStockAlert = notification.type === 'Low Stock' || notification.type === 'Out of Stock';
            
            return (
              <div
                key={notification._id}
                onClick={() => handleNotificationClick(notification)}
                className={`bg-white rounded-xl shadow-md border-l-4 p-6 cursor-pointer transition hover:shadow-lg ${
                  getPriorityColor(notification.priority)
                } ${!notification.isRead ? 'border-l-4' : 'opacity-75'}`}
                style={{ borderLeftColor: notification.color === 'red' ? '#EF4444' : 
                                          notification.color === 'orange' ? '#F59E0B' : 
                                          notification.color === 'green' ? '#10B981' : 
                                          notification.color === 'purple' ? '#8B5CF6' : '#3B82F6' }}
              >
                <div className="flex items-start gap-4">
                  <div className={`p-3 rounded-lg ${getIconColor(notification.color)}`}>
                    {IconComponent ? <IconComponent size={24} /> : <Bell size={24} />}
                  </div>

                  <div className="flex-1">
                    <div className="flex justify-between items-start mb-2">
                      <div>
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className="text-lg font-bold text-gray-800">{notification.title}</h3>
                          {!notification.isRead && (
                            <span className="w-2 h-2 rounded-full animate-pulse" style={{ backgroundColor: '#A8E4A0' }}></span>
                          )}
                        </div>
                        <span className={`text-xs px-2 py-1 rounded-full font-medium ${
                          isStockAlert ? 'bg-red-100 text-red-700' :
                          notification.type === 'GST Alert' ? 'bg-purple-100 text-purple-700' :
                          'bg-green-100 text-green-700'
                        }`}>
                          {notification.type}
                        </span>
                      </div>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          deleteNotification(notification._id);
                        }}
                        className="text-gray-400 hover:text-red-600 transition"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>

                    <p className="text-gray-700 mb-3">{notification.message}</p>

                    {/* Additional Info Based on Type */}
                    {isStockAlert && notification.currentStock !== undefined && (
                      <div className="flex items-center gap-4 text-sm">
                        <div className="flex items-center gap-2 text-gray-600">
                          <TrendingDown size={16} />
                          <span>Current: <strong>{notification.currentStock}</strong> units</span>
                        </div>
                        {notification.minStock && (
                          <div className="text-gray-600">
                            Min Required: <strong>{notification.minStock}</strong> units
                          </div>
                        )}
                        {notification.productName && (
                          <div className="text-gray-600">
                            Product: <strong>{notification.productName}</strong>
                          </div>
                        )}
                      </div>
                    )}

                    {notification.type === 'GST Alert' && notification.daysRemaining && (
                      <div className="flex items-center gap-4 text-sm">
                        <div className="flex items-center gap-2 text-gray-600">
                          <Calendar size={16} />
                          <span>Due: <strong>{formatDate(notification.dueDate)}</strong></span>
                        </div>
                        <span className="text-orange-600 font-medium">
                          {notification.daysRemaining} days remaining
                        </span>
                      </div>
                    )}

                    {notification.type === 'Payment Alert' && notification.amount && (
                      <div className="flex items-center gap-4 text-sm">
                        <div className="flex items-center gap-2 text-gray-600">
                          <DollarSign size={16} />
                          <span>Amount: <strong>₹{notification.amount?.toLocaleString()}</strong></span>
                        </div>
                        {notification.invoiceNumber && (
                          <span className="text-gray-600">Invoice: {notification.invoiceNumber}</span>
                        )}
                      </div>
                    )}

                    <div className="flex items-center gap-2 mt-3 text-xs text-gray-500">
                      <Clock size={14} />
                      <span>{formatTimeAgo(notification.timestamp)}</span>
                      {!notification.isRead && (
                        <span className="ml-2 px-2 py-0.5 bg-green-100 text-green-700 text-xs rounded-full">
                          New
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Notification Detail Modal */}
      {showModal && selectedNotification && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full p-8">
            <div className="flex justify-between items-start mb-6">
              <div className="flex items-center gap-3">
                <div className={`p-3 rounded-lg ${getIconColor(selectedNotification.color)}`}>
                  {(() => {
                    const IconComponent = getIconComponent(selectedNotification.icon);
                    return IconComponent ? <IconComponent size={28} /> : <Bell size={28} />;
                  })()}
                </div>
                <div>
                  <h2 className="text-2xl font-bold text-gray-800">{selectedNotification.title}</h2>
                  <span className={`text-xs px-2 py-1 rounded-full font-medium inline-block mt-1 ${
                    selectedNotification.type === 'Low Stock' || selectedNotification.type === 'Out of Stock' 
                      ? 'bg-red-100 text-red-700' :
                    selectedNotification.type === 'GST Alert' ? 'bg-purple-100 text-purple-700' :
                    'bg-green-100 text-green-700'
                  }`}>
                    {selectedNotification.type}
                  </span>
                </div>
              </div>
              <button
                onClick={() => setShowModal(false)}
                className="text-gray-400 hover:text-gray-600 transition"
              >
                <X size={28} />
              </button>
            </div>

            <div className="space-y-4">
              <div className="p-4 bg-gray-50 rounded-lg">
                <p className="text-gray-700">{selectedNotification.message}</p>
              </div>

              {(selectedNotification.type === 'Low Stock' || selectedNotification.type === 'Out of Stock') && selectedNotification.productName && (
                <>
                  <div className="flex justify-between p-3 bg-red-50 rounded-lg">
                    <span className="font-semibold text-gray-700">Product Name:</span>
                    <span className="font-bold text-gray-800">{selectedNotification.productName}</span>
                  </div>
                  {selectedNotification.currentStock !== undefined && (
                    <div className="flex justify-between p-3 bg-red-50 rounded-lg">
                      <span className="font-semibold text-gray-700">Current Stock:</span>
                      <span className="font-bold text-red-600">{selectedNotification.currentStock} units</span>
                    </div>
                  )}
                  {selectedNotification.minStock && (
                    <div className="flex justify-between p-3 bg-red-50 rounded-lg">
                      <span className="font-semibold text-gray-700">Minimum Required:</span>
                      <span className="font-bold text-gray-800">{selectedNotification.minStock} units</span>
                    </div>
                  )}
                </>
              )}

              {selectedNotification.type === 'GST Alert' && selectedNotification.dueDate && (
                <>
                  <div className="flex justify-between p-3 bg-purple-50 rounded-lg">
                    <span className="font-semibold text-gray-700">Due Date:</span>
                    <span className="font-bold text-gray-800">{formatDate(selectedNotification.dueDate)}</span>
                  </div>
                  {selectedNotification.daysRemaining && (
                    <div className="flex justify-between p-3 bg-purple-50 rounded-lg">
                      <span className="font-semibold text-gray-700">Days Remaining:</span>
                      <span className="font-bold text-purple-600">{selectedNotification.daysRemaining} days</span>
                    </div>
                  )}
                  {selectedNotification.amount && (
                    <div className="flex justify-between p-3 bg-purple-50 rounded-lg">
                      <span className="font-semibold text-gray-700">Amount:</span>
                      <span className="font-bold text-gray-800">₹{selectedNotification.amount?.toLocaleString()}</span>
                    </div>
                  )}
                </>
              )}

              {selectedNotification.type === 'Payment Alert' && (
                <>
                  {selectedNotification.customerName && (
                    <div className="flex justify-between p-3 bg-green-50 rounded-lg">
                      <span className="font-semibold text-gray-700">Customer:</span>
                      <span className="font-bold text-gray-800">{selectedNotification.customerName}</span>
                    </div>
                  )}
                  {selectedNotification.amount && (
                    <div className="flex justify-between p-3 bg-green-50 rounded-lg">
                      <span className="font-semibold text-gray-700">Amount:</span>
                      <span className="font-bold text-green-600">₹{selectedNotification.amount?.toLocaleString()}</span>
                    </div>
                  )}
                  {selectedNotification.invoiceNumber && (
                    <div className="flex justify-between p-3 bg-green-50 rounded-lg">
                      <span className="font-semibold text-gray-700">Invoice Number:</span>
                      <span className="font-bold text-gray-800">{selectedNotification.invoiceNumber}</span>
                    </div>
                  )}
                  {selectedNotification.daysOverdue && (
                    <div className="flex justify-between p-3 bg-red-50 rounded-lg">
                      <span className="font-semibold text-gray-700">Overdue By:</span>
                      <span className="font-bold text-red-600">{selectedNotification.daysOverdue} days</span>
                    </div>
                  )}
                </>
              )}

              <div className="flex justify-between p-3 bg-gray-50 rounded-lg">
                <span className="font-semibold text-gray-700">Timestamp:</span>
                <span className="text-gray-600">{formatDate(selectedNotification.timestamp)}</span>
              </div>

              <div className="flex justify-between p-3 bg-gray-50 rounded-lg">
                <span className="font-semibold text-gray-700">Priority:</span>
                <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                  selectedNotification.priority === 'high' ? 'bg-red-100 text-red-700' :
                  selectedNotification.priority === 'medium' ? 'bg-yellow-100 text-yellow-700' :
                  'bg-green-100 text-green-700'
                }`}>
                  {selectedNotification.priority?.toUpperCase() || 'MEDIUM'}
                </span>
              </div>
            </div>

            <div className="flex gap-3 mt-6">
              {!selectedNotification.isRead && (
                <button
                  onClick={() => {
                    markAsRead(selectedNotification._id);
                    setShowModal(false);
                  }}
                  className="flex-1 px-4 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition"
                >
                  Mark as Read
                </button>
              )}
              <button
                onClick={() => setShowModal(false)}
                className="flex-1 px-4 py-3 rounded-lg font-bold text-white transition"
                style={{ backgroundColor: '#A8E4A0' }}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default NotificationsPage;